const ID='wolf-gold-moon';
const symbol=(value:number)=>ID+'-'+(value<8?value:value===WOLF_WILD?'wild':value===WOLF_SCATTER?'scatter':'money');
const value=(id:string)=>id===ID+'-wild'?WOLF_WILD:id===ID+'-scatter'?WOLF_SCATTER:id===ID+'-money'?WOLF_MONEY:Number(id.slice(ID.length+1));

/** Dedicated Wolf Gold engine. The rules and values are source-backed; the
 * unpublished reel strips are replaced by the explicit local weights below. */
export class WolfSlot extends SlotMain {
 // Never reuse the retired shared engine's purchase mean. Calibrate after rule audit.
 readonly bonusCalibrationKey='wolf-gold-moon:giant-money-v2';
 readonly columns=5;readonly rows=3;readonly mode='lines' as const;readonly paylines=WOLF_LINES;
 readonly bets=[...BET_LEVELS];readonly hasBonus=true;readonly maxWin=10000;readonly usesReferencePayouts=true;
 get bonusSymbol(){return ID+'-scatter';}get bonusTriggerCount(){return 3;}get unlockPriceTenths(){return 1000;}
 readonly rules=['5×3 · 25라인 · 일반 배당은 총베팅/25 기준','협곡 SCATTER는 1·3·5번 릴에만 등장 · 3개는 1배와 5프리스핀','프리스핀은 2~4번 릴을 하나의 3×3 거대 심볼로 표시 · 재진입 +3회','머니 문 6개 → 3회 홀드 리스핀 · 새 문 착지 시 3회 복구','머니 문 15칸 완성 → MEGA 1000배 추가'];
 readonly presentation:SlotPresentation={evidence:'official-rules',anticipationText:'협곡의 달이 떠오릅니다',triggerText:'늑대의 프리스핀',bonusInText:'거대 심볼 · 5회',hitText:'달빛 라인 당첨',totalWinText:'달빛 울음 · 총 당첨',signature:'중앙 3×3 거대 심볼 · 머니 문 홀드 리스핀',uiEffect:'거대 심볼 한 장 표시 · 고정 머니 문 수집',soundCue:'featureLand',anticipationHold:.35,hitHold:.2,outHold:.6};
 readonly config:SlotConfig={id:ID,title:'달빛 울음',subtitle:'MOON HOWL',tag:'GIANT SYMBOL · MONEY RESPIN',color:'#283f56',accent:'#92e9ee',description:this.rules.join('\n'),symbols:[
  ...['들소','독수리','말','퓨마','A','K','Q','J'].map((name,index)=>({id:symbol(index),name,art:index<4?['cat','bird','horse','cat'][index]:'tower',color:'#d5e9e6',weight:[4,5,6,7,10,11,12,13][index],payout:WOLF_LINE_PAYS[index][2]/25})),
  {id:symbol(WOLF_WILD),name:'늑대 · WILD',art:'cat',color:'#ffe7a5',weight:2,payout:WOLF_LINE_PAYS[WOLF_WILD][2]/25},
  {id:symbol(WOLF_SCATTER),name:'협곡 · SCATTER',art:'tower',color:'#ffdd8a',weight:2,payout:0},
  {id:symbol(WOLF_MONEY),name:'머니 문',art:'coin',color:'#fff1a4',weight:9,payout:0},
 ]};
 private pickValue(rng:()=>number,allowScatter:boolean,scatterUsed:boolean,free=false){
  const weights=[4,5,6,7,10,11,12,13,2*(free?1:WOLF_MODEL.baseWild),allowScatter&&!scatterUsed?2*(free?1:WOLF_MODEL.baseScatter):0,9*(free?WOLF_MODEL.freeMoney:WOLF_MODEL.baseMoney)],sum=weights.reduce((a,b)=>a+b,0);let roll=rng()*sum;
  for(let i=0;i<weights.length;i++){roll-=weights[i];if(roll<0)return i;}return 7;
 }
 private board(rng:()=>number,free=false){const board=Array<number>(15);for(let col=0;col<5;col++){let scatter=false;for(let row=0;row<3;row++){const n=this.pickValue(rng,col%2===0,scatter,free);board[row*5+col]=n;scatter ||= n===WOLF_SCATTER;}}return board;}
 private moneyToken(cell:number,rng:()=>number):WolfMoneyToken{
  const roll=rng();if(roll<.008)return{cell,multiple:100,kind:'major'};if(roll<.035)return{cell,multiple:30,kind:'mini'};
  const choices=WOLF_MONEY_VALUES.slice(0,-1),multiple=choices[Math.floor(rng()*rng()*choices.length)];return{cell,multiple,kind:'cash'};
 }
 private moneyLandings(initial:WolfMoneyToken[],rng:()=>number){
  const held=new Set(initial.map(token=>token.cell)),landings:WolfMoneyToken[][]=[];let lives=3;
  while(lives>0&&held.size<15){const landed:WolfMoneyToken[]=[];for(let cell=0;cell<15;cell++)if(!held.has(cell)&&rng()<.105){held.add(cell);landed.push(this.moneyToken(cell,rng));}landings.push(landed);lives=landed.length?3:lives-1;if(landings.length>1024)throw Error('Wolf money respins did not converge');}
  return landings;
 }
 private awards(board:number[],bet:number,giant=false):Win[]{return wolfBaseAwards(board,bet,giant).map(win=>({line:win.line,symbol:symbol(win.symbol),cells:[...win.cells],multiplier:win.multiple,amount:win.amount}));}
 private round(bet:number,rng:()=>number,free=false,opening?:number[]):SpinResult{
  const board=opening?[...opening]:this.board(rng,free),giantCells=WOLF_GIANT_CELLS;let giant:number|undefined;
  if(free){giant=opening?.[2]===WOLF_SCATTER?WOLF_SCATTER:this.pickValue(rng,true,false,true);for(const cell of giantCells)board[cell]=giant;}
  const ids=board.map(symbol),wins=this.awards(board,bet,free),money=board.flatMap((n,cell)=>n===WOLF_MONEY?[this.moneyToken(cell,rng)]:[]);
  let result:SpinResult=money.length>=6?wolfMoneyResult(bet,money,this.moneyLandings(money,rng),{board:ids,wins}):{bet,board:ids,wins,payout:wins.reduce((sum,win)=>sum+win.amount,0)};
  if(giant!==undefined)result.wolfGiant={symbol:symbol(giant),cells:giantCells};result.presentation=this.presentation;return result;
 }
 spin(bet:number,rng:()=>number=Math.random){
  if(!this.bets.includes(bet))throw Error('Invalid Wolf bet');const base=this.round(bet,rng),scatters=(round:SpinResult)=>wolfScatterCells((round.wolfMoneyFeature?.triggerBoard||round.openingBoard||round.board).map(value),!!round.wolfGiant).length;
  const count=scatters(base);if(count<3)return base;
  const result=this.freeSpinSequence(base,()=>this.round(bet,rng,true),round=>round===base?wolfFreeSpins(count):wolfFreeSpins(scatters(round),true));result.featureName='거대 늑대 프리스핀';result.presentation=this.presentation;return result;
 }
 prepareBonusPurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid Wolf bet');
  // Exact conditioning on the three qualifying reels. Gate row probabilities
  // are 1:q:q²; all other cells retain the original non-scatter distribution.
  // This avoids a rare 20,000-attempt purchase failure without selecting payouts.
  const board=Array<number>(15),ordinaryWeight=68+2*WOLF_MODEL.baseWild+9*WOLF_MODEL.baseMoney,q=ordinaryWeight/(ordinaryWeight+2*WOLF_MODEL.baseScatter);
  for(let col=0;col<5;col++){
   let gate=-1;
   if(col%2===0){let roll=rng()*(1+q+q*q);gate=2;for(let row=0;row<3;row++){roll-=q**row;if(roll<0){gate=row;break;}}}
   for(let row=0;row<3;row++)board[row*5+col]=row===gate?WOLF_SCATTER:this.pickValue(rng,false,false);
  }
  const trigger:SpinResult={bet,board:board.map(symbol),payout:0,wins:[],presentation:this.presentation,roundLabel:'BONUS TRIGGER'};
  const sequence=this.freeSpinSequence(trigger,()=>this.round(bet,rng,true),round=>round===trigger?5:wolfFreeSpins(wolfScatterCells((round.wolfMoneyFeature?.triggerBoard||round.openingBoard||round.board).map(value),!!round.wolfGiant).length,true));
  const rounds=sequence.rounds!.slice(1);
  return {...sequence,rounds,board:[...rounds[rounds.length-1].board],wins:rounds.flatMap(r=>r.wins),payout:rounds.reduce((n,r)=>n+r.payout,0),bonusTriggerRound:trigger,featureName:'거대 늑대 프리스핀',presentation:this.presentation};
 }
 evaluate(board:string[],bet:number){if(board.length!==15||!this.bets.includes(bet)||board.some(id=>!this.config.symbols.some(s=>s.id===id)))throw Error('Invalid Wolf spin');const wins=this.awards(board.map(value),bet);return{board:[...board],bet,wins,payout:wins.reduce((sum,win)=>sum+win.amount,0),presentation:this.presentation};}
 demoSpin(bet:number){const board=Array.from({length:15},(_,i)=>(i+Math.floor(i/5))%8);board[5]=board[6]=board[7]=0;return this.round(bet,()=>.8,false,board);}
 bonusDemoSpin(bet:number,nestedMoney=false){
  let seed=84071;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;},baseBoard=Array.from({length:15},(_,i)=>(i+4)%8);baseBoard[0]=baseBoard[2]=baseBoard[4]=WOLF_SCATTER;
  const base=this.round(bet,rng,false,baseBoard),retrigger=Array.from({length:15},(_,i)=>(i+1)%8);retrigger[0]=retrigger[2]=retrigger[4]=WOLF_SCATTER;let freeIndex=0;
  const outerMoney=Array.from({length:15},(_,cell)=>cell%5===0||cell%5===4?WOLF_MONEY:7);
  // Deterministic QA of an allowed outer-six-money outcome, not a probability change.
  const next=()=>{const index=freeIndex++;return nestedMoney&&index===1?this.round(bet,()=>.85,true,outerMoney):this.round(bet,rng,true,index===0?retrigger:undefined);};
  const result=this.freeSpinSequence(base,next,round=>round===base?5:wolfFreeSpins(wolfScatterCells((round.wolfMoneyFeature?.triggerBoard||round.openingBoard||round.board).map(value),!!round.wolfGiant).length,true));
  result.featureName='거대 늑대 프리스핀';result.presentation=this.presentation;return result;
 }
}
