import {FlowControl} from './FlowControl';
import { Node } from 'cc';
import { CellDrop } from '../slots/SlotMain';
import { launch, fall } from './SlotEffects';

export const STANDARD_TUMBLE_TEMPO=1.35;
export const OLYMPUS_TUMBLE_TEMPO=1.55;
export const SUGAR_OPENING_TEMPO=2.1;
export const SUGAR_REFILL_TEMPO=1.85;
export function tumbleOpeningTempo(slotId:string){return slotId==='sugar-lane-rush'?SUGAR_OPENING_TEMPO:slotId==='gates-of-clouds'?OLYMPUS_TUMBLE_TEMPO:STANDARD_TUMBLE_TEMPO;}
export function tumbleRefillTempo(slotId:string){return slotId==='sugar-lane-rush'?SUGAR_REFILL_TEMPO:1.2;}

/** Shared by every tumbling slot. Surviving symbols retain their Node identity. */
export class TumbleAnimator {
 constructor(private columns:number,private rows:number,private cell:number,private gap:number,
  private create:(id:string,x:number,y:number,index:number)=>Node,private tempo=1,private onLand?:(column:number)=>void,private flow?:FlowControl,private onSymbolLand?:(node:Node,id:string,index:number)=>Promise<void>,private onSymbolImpact?:(node:Node,id:string,index:number)=>void,_legacyIncomingGapScale=1,private onMotionEnd?:()=>void,private openingTempo=tempo){}
 private motionStops(count:number){if(!count)this.onMotionEnd?.();return ()=>{if(--count===0)this.onMotionEnd?.();};}
 private position(index:number){return {x:((index%this.columns+this.columns)%this.columns)*(this.cell+this.gap)+this.cell/2,y:-Math.floor(index/this.columns)*(this.cell+this.gap)-this.cell/2};}
 async refill(symbols:Map<number,Node>,drops:CellDrop[]):Promise<void>{
  const previous=new Map(symbols),next=new Map<number,Node>(),motions:Promise<void>[]=[];
  const landedColumns=new Set<number>(),motionStopped=this.motionStops(drops.filter(drop=>drop.from!==drop.to).length);
  for(const drop of drops){
   // Incoming symbols always occupy their full logical source row. Compressing
   // this gap makes a fresh symbol intersect the survivor directly below it.
   const start=this.position(drop.from),end=this.position(drop.to);
   const node=drop.from<0?this.create(drop.symbol,start.x,start.y,drop.to):previous.get(drop.from);
   if(!node?.isValid)throw Error('Missing surviving symbol at '+drop.from);
   next.set(drop.to,node);
   const distance=Math.floor(drop.to/this.columns)-Math.floor(drop.from/this.columns);
   // Never teleport an existing symbol back to a reconstructed start position.
   if(drop.to!==drop.from)motions.push(fall(node,end.x,end.y,(.15+Math.sqrt(Math.abs(distance))*.075)*this.tempo,((drop.to%this.columns)*.017+(this.rows-1-Math.floor(drop.to/this.columns))*.007)*this.tempo,()=>{if(drop.from<0)this.onSymbolImpact?.(node,drop.symbol,drop.to);const col=drop.to%this.columns;if(!landedColumns.has(col)){landedColumns.add(col);this.onLand?.(col);}},this.flow).then(()=>{motionStopped();return drop.from<0?this.onSymbolLand?.(node,drop.symbol,drop.to):undefined;}));
  }
  symbols.clear();next.forEach((node,index)=>symbols.set(index,node));
  await Promise.all(motions);
 }
 async replace(symbols:Map<number,Node>,board:string[]):Promise<void>{
  // A new spin also carries the currently visible symbols down out of the mask.
  const distance=(this.rows+1)*(this.cell+this.gap),outgoing=Array.from(symbols);
  const motionStopped=this.motionStops(outgoing.length+board.filter(symbol=>symbol&&!symbol.endsWith('-void')).length);
  const exiting=outgoing.map(([index,node])=>launch(node,distance,.28*this.openingTempo,Math.min(.15,(index%this.columns)*.025)*this.openingTempo,this.flow).then(()=>{motionStopped();node.destroy();}));
  symbols.clear();
  // Sound the first actual impact in each column, including boards with empty bottom cells.
  const landedColumns=new Set<number>();
  // Retain a staggered opening without a long empty-board pause.
  const entering=board.map((symbol,index)=>{
   if(!symbol||symbol.endsWith('-void'))return Promise.resolve();
   const col=index%this.columns,row=Math.floor(index/this.columns),start=this.position(index-(this.rows+1)*this.columns),end=this.position(index);
   const node=this.create(symbol,start.x,start.y,index);symbols.set(index,node);
   const delay=Math.min(.3,.12+col*.025+(this.rows-1-row)*.01)*this.openingTempo;
   return fall(node,end.x,end.y,.36*this.openingTempo,delay,()=>{this.onSymbolImpact?.(node,symbol,index);if(!landedColumns.has(col)){landedColumns.add(col);this.onLand?.(col);}},this.flow).then(()=>{motionStopped();return this.onSymbolLand?.(node,symbol,index);});
  });
  await Promise.all([...exiting,...entering]);
 }
}
