export function neonAuditRng(initial:readonly number[]){const s=[...initial],rotate=(n:number,bits:number)=>(n<<bits|n>>>(32-bits))>>>0;if(s.length!==4||s.every(n=>n===0)||s.some(n=>!Number.isInteger(n)||n<0||n>0xffffffff))throw Error('Invalid Neon audit state');const next=()=>{const result=Math.imul(rotate(Math.imul(s[1],5),7),9)>>>0,t=s[1]<<9;s[2]^=s[0];s[3]^=s[1];s[1]^=s[2];s[0]^=s[3];s[2]^=t;s[3]=rotate(s[3],11);return result/4294967296;};next.snapshot=()=>s.map(n=>n>>>0);return next;}
