/** A rolling flip starts every 120 ms, reading each 6-column row left to right.
 * The last flip must finish before clovers, pots, or settlement can begin. */
export const BANDIT_REVEAL_INTERVAL=.12;
export async function revealBanditPrizes<T extends {cell:number}>(
 prizes:readonly T[],flip:(prize:T,index:number)=>Promise<void>,wait:(seconds:number)=>Promise<void>,
):Promise<void>{
 const ordered=[...prizes].sort((a,b)=>a.cell-b.cell),motions:Promise<void>[]=[];
 for(const [index,prize]of ordered.entries()){
  motions.push(flip(prize,index));
  if(index<ordered.length-1)await wait(BANDIT_REVEAL_INTERVAL);
 }
 await Promise.all(motions);
}
