import{CRUISE_MODEL as M}from'./CruiseBuilderMath';
import{cruiseInputBoard}from'./CruiseInputBoard';
import {ExpansionSlot, ExpansionFrame, Geometry, expansionCells as cells, randomIndex} from './ExpansionCore';
import {SpinResult} from './SlotMain';

export const CRUISE_BUILDS = [
 {label:'기본 항해 · 무료 20회', count:20},
 {label:'고가 심볼 · 무료 2회', count:2},
 {label:'WILD ×2 · 무료 12회', count:12},
 {label:'VIP 변환 · 무료 12회', count:12},
] as const;
/** Local fixed-budget adaptation. Original variable-price/variable-spin builder is not replicated. */
export class CruiseBuilderSlot extends ExpansionSlot {
 constructor(spec:ConstructorParameters<typeof ExpansionSlot>[0]) {
  super(spec);
  this.config.description=this.config.description.replace('구매는 저장 토큰을 쓰지 않고 같은 네 가지 보너스 중 선택합니다.','보너스 구매는 제공하지 않습니다.');
  const seen=new Set(this.paylines.map(line=>line.join(',')));
  for(let code=0;this.paylines.length<50&&code<243;code++) {
   let n=code;const line=Array.from({length:5},(_,col)=>{const row=n%3;n=Math.floor(n/3);return row*5+col;});
   if(!seen.has(line.join(','))){seen.add(line.join(','));this.paylines.push(line);}
  }
  for(const name of ['vip','double','sticky','wheel'])this.config.symbols.push({id:this.id(name),name,color:'#efd08c',weight:name==='wheel'?1:0,payout:0});
  this.config.symbols.find(s=>s.id===this.id('scatter'))!.weight=4;
 }
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-voyage';}
 isWild(id:string){return super.isWild(id)||id===this.id('vip')||id===this.id('double');}
 bank(bet:number){const saved=this.state(bet,[0]);return saved.reduce((sum,n)=>sum+n,0);}
 private grid(bet:number,rng:()=>number,mode=-1) {
  if(!this.bets.includes(bet)||![-1,0,1,2,3].includes(mode))throw Error('Invalid Cruise bet or mode');
  return cruiseInputBoard(this.config.id,mode<0?M.baseZeroByBet[bet]:M.freeZeroByBet[mode][bet],M.wild,M.gate,M.wheel,rng,mode);
 }
 draw(bet:number,rng:()=>number,_g:Geometry=this.geometry){return this.grid(bet,rng);}
 private freeRound(input:string[],bet:number,rng:()=>number,mode:number) {
  const board=[...input],frames:ExpansionFrame[]=[this.frame(board,'reels',CRUISE_BUILDS[mode].label)];
  if(mode===3&&cells(board,this.id('vip')).length) {
   const selected=randomIndex(rng,4),changed=cells(board,this.id(selected));
   frames.push(this.frame(board,'reveal','VIP · 선택한 고가 심볼을 WILD로',cells(board,this.id('vip')),{actor:{symbol:this.id(selected),cells:changed}}));
   changed.forEach(c=>board[c]=this.id('vip'));
   if(changed.length)frames.push(this.frame(board,'effect','같은 고가 심볼 → VIP WILD',changed));
  }
  const values=board.map(id=>id===this.id('double')?2:1);
  frames.push(this.hit(board,bet,mode===2?'당첨에 참여한 WILD 배수 곱하기':'항해 50라인 당첨',this.geometry,mode===2?{values,wildMode:'product'}:{}));
  return this.round(bet,frames);
 }
 private builds(base:SpinResult,bet:number,rng:()=>number,remainder?:number) {
  const branches=CRUISE_BUILDS.map((build,mode)=>{
   const entry=JSON.parse(JSON.stringify(base)) as SpinResult;
   entry.expansionFeature!.frames.push(this.frame(entry.board,'trigger','항해 토큰 12개 · 보너스 구성 선택',cells(entry.board,this.id('scatter')),{panel:{label:'항해 토큰 사용',values:[12],columns:1}}));
   const rounds=[entry];
   for(let left=build.count-1;left>=0;left--){const round=this.freeRound(this.grid(bet,rng,mode),bet,rng,mode);round.freeSpinsRemaining=left;rounds.push(round);}
   for(const round of rounds.slice(1))for(const frame of round.expansionFeature!.frames)frame.panel={label:'항해 토큰',values:[remainder??0],columns:1};
   const result=this.finish(rounds,{freeSpinsAwarded:build.count,featureOnly:false});
   return remainder===undefined?result:this.progressResult(result,bet,[remainder]);
  });
  return this.choices('모은 토큰으로 항해 구성',CRUISE_BUILDS.map(b=>b.label),branches);
 }
 play(board:string[],bet:number,rng:()=>number) {
  const before=this.bank(bet),tokens=cells(board,this.id('scatter')),after=before+tokens.length;
  const frames:ExpansionFrame[]=[this.frame(board,'reels','항해 토큰 수집',[],{panel:{label:'항해 토큰',values:[before],columns:1}}),this.hit(board,bet,'50라인 당첨')];
  if(tokens.length)frames.push(this.frame(board,'collect','항해 토큰 → 보너스 구성',tokens,{meter:{label:'항해 토큰',before,after,target:12,items:tokens.map(cell=>({cell,value:1}))},panel:{label:'항해 토큰',values:[after],columns:1}}));
  const wheels=cells(board,this.id('wheel'));
  if(wheels.length>=3){const values=[2,3,5,8,12,20,30,50],selected=randomIndex(rng,values.length);frames.push(this.frame(board,'reveal','키잡이 휠 3개 · 상금 휠',wheels,{wheel:{label:'항해 상금 휠',values,selected,unit:'prize',stage:'first'}}),this.prize(board,bet,values[selected],wheels,'항해 휠 상금'));}
  const base=this.round(bet,frames);
  return after<12?this.progressResult(this.finish([base]),bet,[after]):this.builds(base,bet,rng,after-12);
 }
 prepareBonusPurchase(_bet:number,_rng:()=>number):SpinResult {
  throw Error('Cruise BUY unsupported: premium2spin support maximum60bet below98bet target');
 }
}
