const weights=[5,6,7,8,10,12,14,16],cache=new Map<NileInput,Map<number,{high:number;weights:number[];sum:number}>>();
export function nileUniform(rng:()=>number){const value=rng();if(!Number.isFinite(value)||value<0||value>=1)throw Error('Invalid Nile random value');return value;}
export function nileOrdinary(bet:number,rng:()=>number,input:NileInput){const u=nileUniform(rng);if(u>=1-input.wild)return 'wild';const high=input.highByBet[bet]??1;let bets=cache.get(input);if(!bets){bets=new Map();cache.set(input,bets);}let pool=bets.get(bet);if(!pool||pool.high!==high){const w=weights.map((v,i)=>v*(i===0?high:1));pool={high,weights:w,sum:w.reduce((a,b)=>a+b,0)};bets.set(bet,pool);}let roll=u/(1-input.wild)*pool.sum;for(let i=0;i<8;i++){roll-=pool.weights[i];if(roll<0)return i;}return 7;}
