import{BALLROOM_INPUTS}from'./MidnightBallroomMath';
function input(bet:number){const v=BALLROOM_INPUTS.find(r=>r.bet===bet);if(!v)throw Error('Invalid Ballroom wager');return v;}
function categorical(prob:readonly number[],rng:()=>number){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid Ballroom uniform');let mass=0;for(let i=0;i<prob.length;i++){mass+=prob[i];if(u<mass)return i;}return prob.length-1;}
export function ballroomInputBoard(id:string,bet:number,rng:()=>number){const v=input(bet),p=[v.regularZero,...[6,7,8,10,12,14].map(n=>(1-v.regularZero-v.rare-v.wild)*n/57),v.rare,v.wild];return Array.from({length:15},()=>{const n=categorical(p,rng);return id+'-'+(n===8?'wild':n);});}
export function ballroomInputTarget(bet:number,rng:()=>number){const v=input(bet);return categorical(Array(7).fill((1-v.rareTarget)/7).concat([v.rareTarget]),rng);}
