import {KEEP_MODEL as M,keepUniform,keepPot} from './FullMoonKeepMath';
import {packRounds} from './Social2230Rules';
import {BET_LEVELS} from './BetLevels';
import {SlotMain,SlotConfig,SpinResult,Win,SlotPresentation} from './SlotMain';
import {WOLF_LINES} from './WolfRules';
export const KEEP_ID='full-moon-keep';
export const keepSymbol=(n:number)=>KEEP_ID+'-'+(n===10?'wild':n===11?'scatter':n===12?'coin':n);
export interface KeepMoon {cell:number;tier:string;win:Win;}
export interface KeepPlayback {lineWins:Win[];moons:KeepMoon[];coinAward?:Win;coinCount:number;free:boolean;}
export const KEEP_PAYS=[[.6,1.7,5.6],[.4,1,3.6],[.3,.8,2.8],[.2,.7,2.4],[.2,.6,2],[.2,.5,1.6],[.1,.2,.8],[.1,.2,.8],[.1,.2,.3],[.1,.2,.3]];
const TIERS=['MINI','MINOR','MAJOR','ULTRA','GRAND'];
export const keepFreeSpins=(n:number)=>n>=5?10:n===4?7:n===3?5:0;
/** Local2026-10-05 redesign: guaranteed qualifying base moon pots and all-moon
 * free-game pots. Fixed phase inputs, no claim to reproduce original math. */
export class FullMoonKeepSlot extends SlotMain {
 readonly usesLocalPayouts=true;readonly columns=5;readonly rows=3;readonly paylines=WOLF_LINES;readonly bets=[...BET_LEVELS];readonly hasBonus=true;readonly maxWin=10000;
 readonly bonusCalibrationKey=KEEP_ID+':moon-coins-v1';
 get bonusSymbol(){return keepSymbol(11);}
 readonly presentation:SlotPresentation={evidence:'source-title-pending',anticipationText:'달빛이 성문에 모입니다',triggerText:'보름달 성문 개방',bonusInText:'slot.keep.bonusIntro',hitText:'성의 보물을 발견했습니다',totalWinText:'늑대성 총 보상',signature:'당첨선 달 WILD 포트 · 코인 개수 보상',uiEffect:'달 점등 후 포트 수집',soundCue:'featureLand',anticipationHold:.3,hitHold:.2,outHold:.5};
 readonly config:SlotConfig={id:KEEP_ID,title:'보름달 늑대성',subtitle:'FULL MOON KEEP',tag:'MOON POTS · WOLF COINS',color:'#26344e',accent:'#afcdee',description:'slot.keep.rules',symbols:[...['성 문장','은빛 늑대','도끼','방패','장갑','늑대 부적','A','K','Q','J','달 WILD','성문 SCATTER','늑대 코인'].map((name,n)=>({id:keepSymbol(n),name,color:'#accce6',weight:[3,4,5,6,7,8,12,12,13,13,6,1.8,7][n],payout:n<10?KEEP_PAYS[n][2]:0}))]};
 private board(rng:()=>number,free=false,conditional=false){
  const q=free?M.freeGate:M.gate,wild=free?M.freeWild:M.baseWild;
  const board=Array.from({length:15},(_,cell)=>{const weights=[3,4,5,6,7,8,12,12,13,13,cell%5<2?0:wild,0,7];let x=keepUniform(rng)*weights.reduce((a,b)=>a+b,0);for(let n=0;n<weights.length;n++){x-=weights[n];if(x<0)return keepSymbol(n);}return keepSymbol(12);});
  let flags=0;
  if(conditional){const options:Array<{mask:number;mass:number}>=[];let total=0;for(let mask=0;mask<32;mask++){const count=mask.toString(2).replace(/0/g,'').length;if(count<3)continue;const mass=q**count*(1-q)**(5-count);options.push({mask,mass});total+=mass;}let pick=keepUniform(rng)*total;flags=options[options.length-1].mask;for(const option of options){pick-=option.mass;if(pick<0){flags=option.mask;break;}}}
  else for(let col=0;col<5;col++)if(keepUniform(rng)<q)flags|=1<<col;
  for(let col=0;col<5;col++)if(flags&(1<<col))board[Math.floor(keepUniform(rng)*3)*5+col]=this.bonusSymbol;
  return board;
 }
 private validate(board:string[],bet:number){if(!this.bets.includes(bet)||board.length!==15||board.some((id,c)=>!this.config.symbols.some(s=>s.id===id)||(id===keepSymbol(10)&&c%5<2)))throw Error('Invalid keep spin');}
 evaluate(board:string[],bet:number,rng:()=>number=()=>.5,free=false):SpinResult{
  this.validate(board,bet);const lineWins:Win[]=[];
  WOLF_LINES.forEach((line,index)=>{const n=this.config.symbols.findIndex(s=>s.id===board[line[0]]);if(n<0||n>=10)return;const cells:number[]=[];for(const cell of line){if(board[cell]!==keepSymbol(n)&&board[cell]!==keepSymbol(10))break;cells.push(cell);}if(cells.length<3)return;const multiple=KEEP_PAYS[n][cells.length-3];lineWins.push({line:index,symbol:keepSymbol(n),cells,amount:Math.round(bet*multiple),multiplier:multiple});});
  const winningCells=new Set(lineWins.flatMap(w=>w.cells));const moons:KeepMoon[]=[];
  const eligible=free?board.flatMap((id,cell)=>id===keepSymbol(10)?[cell]:[]):Array.from(winningCells);
  for(const cell of eligible)if(board[cell]===keepSymbol(10)){const {tier,multiple}=keepPot(keepUniform(rng),free);moons.push({cell,tier:TIERS[tier],win:{line:-2,symbol:keepSymbol(10),cells:[cell],amount:bet*multiple,multiplier:multiple}});}
  const coins=board.flatMap((id,c)=>id===keepSymbol(12)?[c]:[]),count=coins.length,multiple=count>=15?10000:count>=12?300:count>=9?80:count>=7?30:count>=5?10:0;
  const coinAward=multiple?{line:-3,symbol:keepSymbol(12),cells:coins,amount:bet*multiple,multiplier:multiple}:undefined;
  const wins=[...lineWins,...moons.map(m=>m.win),...(coinAward?[coinAward]:[])];let left=bet*this.maxWin;for(const w of wins){w.amount=Math.min(left,w.amount);left-=w.amount;}
  return{bet,board:[...board],wins,payout:bet*this.maxWin-left,keepFeature:{lineWins,moons,coinAward,coinCount:count,free},presentation:this.presentation};
 }
 private sequence(base:SpinResult,rng:()=>number){
  const initial=keepFreeSpins(base.board.filter(s=>s===this.bonusSymbol).length);if(!initial)return base;
  const rounds=[base];let remaining=initial,awarded=initial,paid=base.payout,played=0;
  while(remaining>0&&paid<base.bet*this.maxWin){remaining--;played++;const round=this.evaluate(this.board(rng,true),base.bet,rng,true);let left=base.bet*this.maxWin-paid;for(const win of round.wins){win.amount=Math.min(left,win.amount);left-=win.amount;}round.payout=round.wins.reduce((a,w)=>a+w.amount,0);paid+=round.payout;
   const extra=Math.min(keepFreeSpins(round.board.filter(s=>s===this.bonusSymbol).length),100-awarded);remaining+=extra;awarded+=extra;round.freeSpinsAdded=extra||undefined;round.freeSpinsRemaining=remaining;round.roundLabel='FREE SPINS · '+played;rounds.push(round);
  }
  return packRounds(rounds,{freeSpinsAwarded:initial,presentation:this.presentation,featureName:'보름달 성문 무료 회전',bonusEndReason:paid>=base.bet*this.maxWin?'max-win':'spins-exhausted'});
 }
 spin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid Keep bet');return this.sequence(this.evaluate(this.board(rng),bet,rng),rng);}
 prepareBonusPurchase(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid Keep bet');const base:SpinResult={bet,board:this.board(rng,false,true),wins:[],payout:0,presentation:this.presentation},result=this.sequence(base,rng);return packRounds(result.rounds!.slice(1),{freeSpinsAwarded:result.freeSpinsAwarded,presentation:this.presentation,featureName:result.featureName,bonusEndReason:result.bonusEndReason,bonusTriggerRound:base});}
 demoSpin(bet:number){const board=Array.from({length:15},(_,i)=>keepSymbol((i+Math.floor(i/5))%10));board[5]=board[6]=keepSymbol(1);board[7]=keepSymbol(10);for(const c of [0,3,4,10,14])board[c]=keepSymbol(12);return this.evaluate(board,bet,()=>.1);}
 bonusDemoSpin(bet:number){let seed=912;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};return this.prepareBonusPurchase(bet,rng);}
}
