import{gapUniform,gapRestLabel}from'./GapInputBoard';
/** Independent uniform-row SCAT flags conditioned>=3, with unchanged ordinary labels. */
export function maskConditionalBoard(id:string,q:number,high:number,wild:number,gate:number,rng:()=>number){
 const choices=[];let total=0;for(let mask=0;mask<32;mask++){let count=0;for(let c=0;c<5;c++)count+=mask>>c&1;if(count<3)continue;const mass=gate**count*(1-gate)**(5-count);choices.push({mask,mass});total+=mass;}let roll=gapUniform(rng)*total,selected=31;for(const choice of choices){roll-=choice.mass;if(roll<0){selected=choice.mask;break;}}
 const board=Array.from({length:15},()=>{const u=gapUniform(rng);return id+'-'+(u<q?'0':gapRestLabel(high,wild,(u-q)/(1-q)));});for(let c=0;c<5;c++)if(selected>>c&1)board[Math.floor(gapUniform(rng)*3)*5+c]=id+'-scatter';return board;
}
