import {USD_COIN_PACKS,LEGACY_COIN_PACKS} from './EconomyBalance';
/** USD reference prices; native UI must use the localized Google Play price. */
export const coinPacks=USD_COIN_PACKS;
export const restorableCoinPacks=[...coinPacks,...LEGACY_COIN_PACKS];
export const referencePrice=(pack:typeof coinPacks[number],locale='en-US')=>typeof Intl!=='undefined'&&typeof Intl.NumberFormat==='function'?new Intl.NumberFormat(locale,{style:'currency',currency:'USD'}).format(pack.priceUSDCents/100):'USD '+(pack.priceUSDCents/100).toFixed(2);
export const packValueMultiple=(pack:typeof coinPacks[number])=>(pack.coins/pack.priceUSDCents)/(coinPacks[0].coins/coinPacks[0].priceUSDCents);
export interface VerifiedPurchase {transactionId:string;walletBalance:number;save:unknown;revision:number;}
export interface PurchaseGateway {
 readonly ready:boolean;
 loadPrices?():Promise<Record<string,string>>;
 purchaseAndVerify(productId:string):Promise<VerifiedPurchase>;
 restorePurchases():Promise<VerifiedPurchase[]>;
}
export class CoinShop {
 constructor(private gateway:PurchaseGateway|null=null){}
 get ready(){return this.gateway?.ready===true;}
 async purchase(productId:string){
  if(!coinPacks.some(p=>p.id===productId))throw Error('Unknown product');
  if(!this.gateway?.ready)throw Error('Google Play 스토어에 연결 중입니다. 잠시 후 다시 시도해 주세요.');
  return this.gateway.purchaseAndVerify(productId);
 }
 loadPrices(){return this.gateway?.loadPrices?.()??Promise.resolve({});}
 restore(){return this.gateway?.ready?this.gateway.restorePurchases():Promise.resolve([]);}
}
