import {SlotMain,SpinResult} from './SlotMain';
export const mathTargets={rtp:.98,bigWin:.0175,feature:.0175,baseHit:.40};
const edges=[0,.1,.25,.5,1,2,5,10,20,30,50,100,200,500,1000,Infinity];
export function mathBin(r:SpinResult){const multiple=r.payout/r.bet;const bucket=multiple===0?0:edges.findIndex(edge=>edge>multiple)+1;return `${Number(!!r.rounds&&r.rounds.length>1)}:${Number((r.rounds?.[0]||r).payout>0)}:${Number((r.rounds?.[0]||r).payout>=r.bet*10)}:${bucket}`;}
export function mathKey(slot:SlotMain,bet:number){const choice=(slot as SlotMain&{bonusChoice?:number}).bonusChoice;return slot.config.id+(choice===undefined?'':':'+choice)+'@'+bet;}
/** Compatibility entry point. Fixed symbol/event inputs belong to each
 * engine. Never choose or reject a result by its paid amount or hit category. */
export function balancedSpin(_slot:SlotMain,_bet:number,_rng:()=>number,sample:()=>SpinResult){return sample();}
