import type {ExpansionFrame} from '../slots/ExpansionCore';

export const BUILDER_WHEEL_SECONDS=3.8;
export const BUILDER_WHEEL_RESULT_SECONDS=1.6;
// Centers measured from the downloaded seven-sector artwork, clockwise from top.
export const BUILDER_WHEEL_ANGLES=[0,55,105,155,205,255,305] as const;
export const BUILDER_WHEEL_KEYS=['saw','mansion','mega','mini','minor','major','grand'] as const;

/** Describe only the currently presented event and its settled Win objects. */
export function builderHouseFlow(frame:ExpansionFrame|null,busy:boolean){
 const event=frame?.builderHouse,phase=event?.phase,levels=frame?.houseLevels||[];
 const stage=!busy?-1:phase&&['reveal','wind','pay','clear'].includes(phase)?2:event?1:0;
 let name='idle';const params:Record<string,string|number>={count:frame?.cells.length||0,spin:event?.spin||0,remaining:event?.remaining||0};
 if(event){
  name=phase!;
  if(phase==='grow'){
   name=event.mode==='mega'&&frame?.actor?'megaLand':event.source!==undefined&&event.source!==event.target?'redirect':'grow';
   const target=event.target??frame?.cells[0]??0;params.cell=target+1;params.before=event.beforeLevels?.[target]||0;params.after=levels[target]||0;
  }
  if(phase==='spin'&&frame?.action==='win')name=frame.wins.length?'lineWin':'miss';
 }else if(frame?.wheel)name='wheelGuide';
 else if(frame?.action==='trigger')name=frame.board[frame.cells[0]]==='builder-house-rise-wheel'?'wheelTrigger':'hatTrigger';
 else if(frame?.wins.length)name='lineWin';
 return {stage,key:'ui.builder.'+name,params,counts:[1,2,3].map(level=>levels.filter(v=>v===level).length)};
}
