/** Durable, bounded diagnostics. Wallet, user profile and auth tokens are never copied. */
export interface CrashContext {slot:string;phase:string;round:string;auto:string;version:string;}
export interface CrashReport {id:string;time:number;kind:string;message:string;stack:string;context:CrashContext;}
const KEY='pocket-crash-reports-v1';
export function scrubError(value:unknown,max=3000){return String(value??'').replace(/https?:\/\/[^\s)]+/g,url=>url.replace(/[?#].*/,'')) .replace(/Bearer\s+\S+/gi,'Bearer [redacted]').replace(/\beyJ[\w.-]+/g,'[redacted]').replace(/[\w.+-]+@[\w.-]+\.[a-z]+/gi,'[email]').slice(0,max);}
export class CrashReports {
 private rows:CrashReport[]=[];private sending=false;private last='';private lastAt=0;
 constructor(private storage:{getItem(k:string):string|null;setItem(k:string,v:string):void},private context:()=>CrashContext,private send:(r:CrashReport)=>Promise<void>){try{const rows=JSON.parse(storage.getItem(KEY)||'[]');if(Array.isArray(rows))this.rows=rows.filter(r=>r&&typeof r.id==='string'&&typeof r.message==='string').slice(-30);}catch{}}
 capture(kind:string,error:unknown){try{const e=error as {message?:string;stack?:string},message=scrubError(e?.message??error,1000),now=Date.now(),key=kind+message;if(key===this.last&&now-this.lastAt<10000)return;this.last=key;this.lastAt=now;this.rows.push({id:now.toString(36)+'-'+Math.random().toString(36).slice(2,14),time:now,kind:kind.slice(0,40),message,stack:scrubError(e?.stack||''),context:this.context()});this.rows=this.rows.slice(-30);this.persist();void this.flush();}catch{}}
 private persist(){try{this.storage.setItem(KEY,JSON.stringify(this.rows));}catch{}}
 async flush(){if(this.sending)return;this.sending=true;try{for(const row of [...this.rows]){await this.send(row);this.rows=this.rows.filter(r=>r.id!==row.id);this.persist();}}catch{/* Keep failed reports across reload; never recursively report transport errors. */}finally{this.sending=false;}}
 install(browserEvents=true){if(!browserEvents||typeof window==='undefined'||typeof window.addEventListener!=='function'||typeof window.removeEventListener!=='function')return()=>{};const error=(e:ErrorEvent)=>this.capture('error',e.error||e.message),rejection=(e:PromiseRejectionEvent)=>this.capture('unhandledrejection',e.reason),online=()=>void this.flush();window.addEventListener('error',error);window.addEventListener('unhandledrejection',rejection);window.addEventListener('online',online);return()=>{window.removeEventListener('error',error);window.removeEventListener('unhandledrejection',rejection);window.removeEventListener('online',online);};}
}
