import {ExpansionSlot,ExpansionFrame,expansionRng} from './ExpansionCore';
import {SpinResult,Win} from './SlotMain';
import {packRounds} from './Social2230Rules';
import {jadeSample,jadeBoard,jadeAwards,JadeRound,JadeTile,JADE_INPUTS,JADE_HEIGHTS,JADE_PAYTABLE,JADE_MAX_WIN,JADE_WILD,JADE_SCATTER} from './JadeTileMath';
export const JADE_ID='jade-tile-cascade-ii';
export interface JadePresentation {free:boolean;multiplier:number;gold:number[];phase:'spin'|'win'|'clear'|'drop'|'wild'|'multiplier'|'trigger'|'settled';}
export class JadeTileSlot extends ExpansionSlot {
 readonly maxWin=JADE_MAX_WIN;
 constructor(){super({requestNumber:0,id:JADE_ID,title:'slot.jade.title',subtitle:'JADE TILE CASCADE II',mode:'ways',columns:5,rows:5,symbolNames:[],feature:'ui.jade.signature',managementNumber:110});
  this.config.color='#123e37';this.config.accent='#edcc75';this.config.tag='ui.jade.tag';
  this.config.description='slot.jade.rules';
  Object.assign(this.presentation,{anticipationText:'ui.jade.spin',triggerText:'ui.jade.trigger',bonusInText:'ui.jade.freeTitle',hitText:'ui.jade.win',totalWinText:'ui.jade.settled'});
  this.config.symbols=Array.from({length:11},(_,i)=>({name:'slot.jade.symbol.'+i,id:this.id(i===9?'wild':i===10?'scatter':i),color:i===10?'#db4935':'#efd08c',weight:i<9?1:0,payout:i<9?JADE_PAYTABLE[i][2]/20:0}));
 }
 unit(symbol:number,count:number){return JADE_PAYTABLE[symbol]?.[count-3]/20||0;}
 evaluate(board:string[],bet:number){const numeric=board.map(id=>({symbol:!id?-1:id.endsWith('-wild')?9:id.endsWith('-scatter')?10:Number(id.slice((JADE_ID+'-').length)),gold:false}));const wins=jadeAwards(numeric,1).map(a=>({line:-1,symbol:this.id(a.symbol),cells:a.cells,amount:Math.round(a.multiple*bet),multiplier:a.multiple}));return {board:[...board],bet,wins,payout:wins.reduce((sum,w)=>sum+w.amount,0)};}
 get bonusSymbol(){return this.id('scatter');}
 get bonusCalibrationKey(){return JADE_ID+':fixed-v1';}
 draw(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid bet');return this.symbolsFor(jadeBoard(rng,false,JADE_INPUTS.base));}
 idleBoard(){return this.symbolsFor(jadeBoard(expansionRng(110),false,JADE_INPUTS.base));}
 reelHeights(){return [...JADE_HEIGHTS];}
 private symbolsFor(board:JadeTile[]){return board.map(t=>t.symbol<0?'':this.id(t.symbol===JADE_WILD?'wild':t.symbol===JADE_SCATTER?'scatter':t.symbol));}
 private transport(round:JadeRound,bet:number,free:boolean):SpinResult{
  const frames:ExpansionFrame[]=[];
  const add=(board:JadeTile[],action:ExpansionFrame['action'],phase:JadePresentation['phase'],multiplier:number,cells:number[]=[],extra:Partial<ExpansionFrame>={})=>{
   frames.push(this.frame(this.symbolsFor(board),action,'ui.jade.'+phase,cells,{jade:{free,multiplier,gold:board.flatMap((t,c)=>t.gold?[c]:[]),phase},...extra}));
  };
  const first=round.stages[0];add(first.board,'reels','spin',first.multiplier);
  for(const stage of round.stages){
   if(!stage.awards.length)continue;
   const wins:Win[]=stage.awards.map(a=>({line:-1,symbol:this.id(a.symbol),cells:[...a.cells],amount:bet*a.multiple,multiplier:a.multiple}));
   add(stage.board,'win','win',stage.multiplier,Array.from(new Set(wins.flatMap(w=>w.cells))),{wins});
   if(!stage.drop)break;
   const empty=stage.board.map((t,c)=>stage.removed.includes(c)?{symbol:-1,gold:false}:{...t});
   add(empty,'remove','clear',stage.multiplier,stage.removed);
   add(stage.drop,'drop','drop',stage.multiplier,[],{moves:stage.moves!.map(m=>({...m,symbol:this.symbolsFor(stage.drop!)[m.to]}))});
   const converted=stage.drop.map(t=>({...t}));for(const cell of stage.converted!)converted[cell]={symbol:JADE_WILD,gold:false};
   if(stage.converted!.length)add(converted,'effect','wild',stage.multiplier,stage.converted);
   add(converted,'state','multiplier',stage.nextMultiplier);
  }
  const last=round.stages[round.stages.length-1];
  const cells=last.board.flatMap((t,c)=>t.symbol===JADE_SCATTER?[c]:[]);
  add(last.board,round.added?'trigger':'state',round.added?'trigger':'settled',last.multiplier,round.added?cells:[]);
  return this.round(bet,frames,free?{freeSpinsRemaining:round.remaining,freeSpinsAdded:round.added||undefined,roundLabel:'ui.jade.freeTitle'}:{});
 }
 private result(bet:number,rng:()=>number,purchase:boolean){
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  const sample=jadeSample(rng,purchase),rounds=sample.rounds.map((r,i)=>this.transport(r,bet,purchase||i>0));
  // Currency rounding only, cumulative to avoid rounding inflation at low bets.
  let exact=0,paid=0;for(const round of rounds){for(const win of round.wins){exact+=win.amount;const next=Math.min(bet*this.maxWin,Math.round(exact));win.amount=next-paid;paid=next;}round.payout=round.wins.reduce((n,w)=>n+w.amount,0);}
  const result=rounds.length===1?rounds[0]:packRounds(rounds,{featureOnly:false,freeSpinsAwarded:sample.awarded,featureName:'ui.jade.freeTitle',presentation:this.presentation});
  if(paid>=bet*this.maxWin)result.bonusEndReason='max-win';
  return result;
 }
 spin(bet:number,rng:()=>number=Math.random){return this.result(bet,rng,false);}
 play(_board:string[],bet:number,rng:()=>number){return this.spin(bet,rng);}
 prepareBonusPurchase(bet:number,rng:()=>number){
  const result=this.result(bet,rng,true);
  // A conditioned scatter entrance is presentation only; never sample by award.
  let board:JadeTile[],attempts=0;do{if(++attempts>100000)throw Error('Jade purchase entrance did not terminate');board=jadeBoard(rng,false,JADE_INPUTS.base);}while(board.filter(t=>t.symbol===JADE_SCATTER).length!==3);
  const strings=this.symbolsFor(board),cells=board.flatMap((t,c)=>t.symbol===JADE_SCATTER?[c]:[]),jade:JadePresentation={free:false,multiplier:1,gold:board.flatMap((t,c)=>t.gold?[c]:[]),phase:'spin'};
  result.bonusTriggerRound=this.round(bet,[this.frame(strings,'reels','ui.jade.spin',[],{jade}),this.frame(strings,'trigger','ui.jade.trigger',cells,{jade:{...jade,phase:'trigger'}})]);
  return result;
 }
 demoSpin(bet:number){return this.spin(bet,expansionRng(20261005));}
 bonusDemoSpin(bet:number){return this.prepareBonusPurchase(bet,expansionRng(20261006));}
}
