import {BET_LEVELS} from './BetLevels';
import {BELL_PROBABILITIES} from './TenthBellMath';
/** Exactly fifteen fixed IID inputs. No outcome inspection, rejection or progress forcing. */
export function bellInputBoard(id:string,bet:number,rng:()=>number):string[]{
 if(!BET_LEVELS.includes(bet))throw Error('Invalid Bell wager');
 return Array.from({length:15},()=>{const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid Bell uniform');let mass=0;for(let n=0;n<10;n++){mass+=BELL_PROBABILITIES[n];if(u<mass)return id+'-'+(n===8?'wild':n===9?'scatter':n);}return id+'-scatter';});
}
