/** Samples fixed phase inputs, before source awards and choice generation. */
export function cruiseInputBoard(id:string,zero:number,wild:number,token:number,wheel:number,rng:()=>number,mode=-1){
 if(!Number.isFinite(zero)||!Number.isFinite(wild)||zero<0||wild<0||zero+wild>1||!Number.isFinite(token)||token<0||token>1||!Number.isFinite(wheel)||wheel<0||wheel>1||![-1,0,1,2,3].includes(mode))throw Error('Invalid Cruise input frequencies');
 const uniform=()=>{const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid Cruise input uniform');return u;},rest=mode===1?[6,7,8]:[6,7,8,10,12,14,16],sum=rest.reduce((a,b)=>a+b,0),pool=[zero,...rest.map(v=>(1-zero-wild)*v/sum),wild];
 const symbol=()=>{let u=uniform(),n=pool.length-1;for(let i=0;i<pool.length;i++){u-=pool[i];if(u<0){n=i;break;}}if(n!==pool.length-1)return id+'-'+n;if(mode===2)return id+'-double';if(mode===3&&uniform()<.5)return id+'-vip';return id+'-wild';};
 if(mode>=0)return Array.from({length:15},symbol);
 const board=Array<string>(15);for(let col=0;col<5;col++){const t=uniform()<token,tr=Math.floor(uniform()*3),w=uniform()<wheel,rows=[0,1,2].filter(r=>!t||r!==tr),wr=rows[Math.floor(uniform()*rows.length)];for(let r=0;r<3;r++)board[r*5+col]=symbol();if(t)board[tr*5+col]=id+'-scatter';if(w)board[wr*5+col]=id+'-wheel';}return board;
}
