export function bearPool(zero:number,wild:number,first:boolean){
 if(!Number.isFinite(zero)||!Number.isFinite(wild)||zero<0||wild<0||zero+(first?0:wild)>1)throw Error('Invalid Bear frequencies');
 const rest=[6,7,8,10,12,14,16],total=73;return[zero,...rest.map(w=>(1-zero-(first?0:wild))*w/total),first?0:wild];
}
export function bearInputBoard(id:string,firstZero:number,otherZero:number,wild:number,gate:number,rng:()=>number,conditional=false){
 const uniform=()=>{const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid Bear input uniform');return u;};let mask=0;
 if(conditional){const options=[];for(let m=0;m<32;m++){const k=Array.from({length:5},(_,c)=>+(!!(m&(1<<c)))).reduce((a,b)=>a+b,0);if(k>=3)options.push({mask:m,p:gate**k*(1-gate)**(5-k)});}let u=uniform()*options.reduce((n,q)=>n+q.p,0);mask=options[options.length-1].mask;for(const q of options){u-=q.p;if(u<0){mask=q.mask;break;}}}
 const board=Array<string>(15);for(let col=0;col<5;col++){const flag=conditional?!!(mask&(1<<col)):uniform()<gate,row=Math.floor(uniform()*3),pool=bearPool(col<2?firstZero:otherZero,wild,col<2);for(let r=0;r<3;r++){let u=uniform(),symbol=7;for(let s=0;s<pool.length;s++){u-=pool[s];if(u<0){symbol=s;break;}}board[r*5+col]=id+'-'+(symbol===8?'wild':symbol);}if(flag)board[row*5+col]=id+'-scatter';}return board;
}
