/** Original local input model. Reference rules: PG Soft Mahjong Ways 2.
 * Fixed symbol distributions, no payout fitting/rejection in a live spin. */
export const JADE_HEIGHTS=[4,5,5,5,4] as const;
export const JADE_PAYTABLE=[[10,25,50],[8,20,40],[6,15,30],[5,10,15],[3,5,12],[3,5,12],[2,4,10],[1,3,6],[1,3,6]] as const;
export const JADE_WILD=9,JADE_SCATTER=10,JADE_MAX_WIN=100000;
export const JADE_BASE_MULTIPLIERS=[1,2,3,5],JADE_FREE_MULTIPLIERS=[2,4,6,10];
export interface JadeInput {high:number;skew:number;scatter:number;gold:number;wild:number;}
export const JADE_INPUTS:{base:JadeInput;free:JadeInput;purchase:JadeInput}={
 base:{high:.2,skew:9.5,scatter:.015572,gold:.08,wild:.001},
 free:{high:.4,skew:5,scatter:.006,gold:.10,wild:.003},
 purchase:{high:.8,skew:5.68117,scatter:.006,gold:.15,wild:.005},
};
export interface JadeTile {symbol:number;gold:boolean;}
export interface JadeAward {symbol:number;cells:number[];ways:number;length:number;multiple:number;}
export interface JadeStage {board:JadeTile[];multiplier:number;awards:JadeAward[];removed:number[];drop?:JadeTile[];moves?:{from:number;to:number}[];converted?:number[];nextMultiplier:number;}
export interface JadeRound {stages:JadeStage[];payout:number;scatters:number;added:number;remaining?:number;}
function random(rng:()=>number){const n=rng();if(!Number.isFinite(n)||n<0||n>=1)throw Error('Invalid Jade RNG');return n;}
export function jadeTile(rng:()=>number,col:number,free:boolean,input:JadeInput,scatterAllowed=true):JadeTile {
 const x=random(rng),middle=col>0&&col<4;
 if(scatterAllowed&&x<input.scatter)return{symbol:JADE_SCATTER,gold:false};
 // Once this reel already has a scatter, its disabled probability mass goes
 // to regular tiles, not to WILD. WILD keeps its declared input probability.
 if(middle&&x<(scatterAllowed?input.scatter:0)+input.wild)return{symbol:JADE_WILD,gold:false};
 // High symbols have their own fixed relative weight; all nine remain possible.
 const weights=[input.high,input.high,input.high,1,1,1,1,1,1];weights[3+col]=input.skew;const sum=3*input.high+5+input.skew;
 let n=random(rng)*sum,symbol=8;for(let i=0;i<9;i++){n-=weights[i];if(n<0){symbol=i;break;}}
 return{symbol,gold:middle&&(free&&col===2||random(rng)<input.gold)};
}
export function jadeBoard(rng:()=>number,free:boolean,input:JadeInput){
 const board:JadeTile[]=Array.from({length:25},()=>({symbol:-1,gold:false}));
 for(let col=0;col<5;col++){let scatter=false;for(let row=0;row<JADE_HEIGHTS[col];row++){const t=jadeTile(rng,col,free,input,!scatter);scatter||=t.symbol===JADE_SCATTER;board[row*5+col]=t;}}return board;
}
export function jadeAwards(board:JadeTile[],multiplier:number):JadeAward[]{
 const awards:JadeAward[]=[];
 for(let symbol=0;symbol<9;symbol++){
  let ways=1,length=0;const cells:number[]=[];let actual=false;
  for(let col=0;col<5;col++){const found:number[]=[];for(let row=0;row<JADE_HEIGHTS[col];row++){const cell=row*5+col,s=board[cell].symbol;if(s===symbol||s===JADE_WILD){found.push(cell);actual||=s===symbol;}}
   if(!found.length)break;ways*=found.length;length++;cells.push(...found);
  }
  if(length>=3&&actual)awards.push({symbol,cells,ways,length,multiple:JADE_PAYTABLE[symbol][length-3]*ways*multiplier/20});
 }return awards;
}
export function jadeRound(rng:()=>number,free:boolean,input:JadeInput,record=true,opening?:JadeTile[]):JadeRound{
 let board=opening?opening.map(t=>({...t})):jadeBoard(rng,free,input),payout=0,index=0;const stages:JadeStage[]=[],ladder=free?JADE_FREE_MULTIPLIERS:JADE_BASE_MULTIPLIERS;
 while(true){
  const multiplier=ladder[Math.min(index,3)],awards=jadeAwards(board,multiplier),matched=new Set(awards.flatMap(a=>a.cells)),removed=Array.from(matched).filter(c=>!board[c].gold),nextMultiplier=ladder[Math.min(index+1,3)];
  const stage:JadeStage={board:board.map(t=>({...t})),multiplier,awards,removed,nextMultiplier};payout+=awards.reduce((n,a)=>n+a.multiple,0);
  if(!awards.length||payout>=JADE_MAX_WIN){if(record)stages.push(stage);break;}
  const drop:JadeTile[]=Array.from({length:25},()=>({symbol:-1,gold:false})),moves:{from:number;to:number}[]=[],converted:number[]=[];
  for(let col=0;col<5;col++){
   const cells=Array.from({length:JADE_HEIGHTS[col]},(_,row)=>(JADE_HEIGHTS[col]-row-1)*5+col),survivors=cells.filter(c=>!removed.includes(c));let hasScatter=survivors.some(c=>board[c].symbol===JADE_SCATTER);
   cells.forEach((to,i)=>{const from=survivors[i]??col-5*(i-survivors.length+1);const t=from>=0?{...board[from]}:jadeTile(rng,col,free,input,!hasScatter);hasScatter||=t.symbol===JADE_SCATTER;drop[to]=t;moves.push({from,to});if(from>=0&&matched.has(from)&&t.gold)converted.push(to);});
  }
  stage.drop=drop.map(t=>({...t}));stage.moves=moves;stage.converted=converted;if(record)stages.push(stage);
  board=drop;for(const cell of converted)board[cell]={symbol:JADE_WILD,gold:false};index++;
  if(index>10000)throw Error('Jade cascade did not terminate');
 }
 const scatters=board.filter(t=>t.symbol===JADE_SCATTER).length;
 return{stages,payout:Math.min(JADE_MAX_WIN,payout),scatters,added:scatters>=3?10+(scatters-3)*2:0};
}
export function jadeSample(rng:()=>number,purchase=false,record=true,inputs=JADE_INPUTS){
 const rounds:JadeRound[]=[];let base=0,bonus=0,remaining=0,awarded=0;
 if(!purchase){const r=jadeRound(rng,false,inputs.base,record);base=r.payout;remaining=awarded=r.added;rounds.push(r);}else remaining=awarded=10;
 while(remaining>0&&base+bonus<JADE_MAX_WIN){
  remaining--;const r=jadeRound(rng,true,purchase?inputs.purchase:inputs.free,record);remaining+=r.added;r.remaining=remaining;bonus+=r.payout;rounds.push(r);
  if(rounds.length>10000)throw Error('Jade free spins did not terminate');
 }
 return{rounds,base,bonus:Math.min(JADE_MAX_WIN-base,bonus),awarded,payout:Math.min(JADE_MAX_WIN,base+bonus)};
}
