import {CIRCUS_INPUTS,CIRCUS_GATE_RATE,CIRCUS_ONE_WILD_RATE} from './CircusMath';
const inputs=CIRCUS_INPUTS.map(row=>({...row,regular:[row.regularZero,...[6,7,8,10,12,14,16].map(n=>(1-row.regularZero)*n/73)]}));
const cells=[2,3,4,7,8,9,12,13,14];
const uniform=(rng:()=>number)=>{const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid circus uniform');return u;};
function input(bet:number){const row=inputs.find((r:any)=>r.bet===bet);if(!row)throw Error('Invalid circus wager');return row;}
function regular(id:string,p:number[],rng:()=>number){const u=uniform(rng);let sum=0;for(let n=0;n<8;n++){sum+=p[n];if(u<sum)return id+'-'+n;}return id+'-7';}
export function circusInputGate(id:string,bet:number,rng:()=>number){
 const p=input(bet).regular,board=Array.from({length:15},()=>regular(id,p,rng)),a=Number(regular(id,p,rng).slice((id+'-').length));
 let b=Math.floor(uniform(rng)*7);if(b>=a)b++;
 for(let row=0;row<3;row++){board[row*5]=id+'-'+a;board[row*5+1]=id+'-'+b;}
 const first=Math.floor(uniform(rng)*9);let second=Math.floor(uniform(rng)*8);if(second>=first)second++;
 board[cells[first]]=board[cells[second]]=id+'-wild';return board;
}
export function circusInputBoard(id:string,bet:number,rng:()=>number){
 input(bet);if(uniform(rng)<CIRCUS_GATE_RATE)return circusInputGate(id,bet,rng);
 const board=Array.from({length:15},()=>regular(id,input(bet).regular,rng));
 if(uniform(rng)<CIRCUS_ONE_WILD_RATE)board[Math.floor(uniform(rng)*15)]=id+'-wild';return board;
}
export function circusInputRescue(id:string,bet:number,rng:()=>number,mode:'natural'|'purchase'='natural'){
 if(!['natural','purchase'].includes(mode))throw Error('Invalid circus mode');const row=input(bet),w=mode==='natural'?row.naturalWild:row.purchaseWild,u=uniform(rng);
 return u<w?id+'-wild':id+'-'+Math.min(7,Math.floor((u-w)/(1-w)*8));
}
