import {ExpansionSlot,ExpansionFrame,ExpansionAction,Geometry,randomIndex as ri} from './ExpansionCore';
import {GODDESS_MODEL,goddessUniform,goddessOrdinary} from './GoddessMath';
export class SunGoddessSlot extends ExpansionSlot {
 private drawingFree=false;
 frame(board:string[],action:ExpansionAction,caption:string,cells:number[]=[],extra:Partial<ExpansionFrame>={},g:Geometry=this.geometry):ExpansionFrame{
  if(Object.keys(extra).some(key=>key!=='wins'))return super.frame(board,action,caption,cells,extra,g);
  // The source frame keeps the original wins after serializing and discarding
  // their clone. Preserve those references without that redundant JSON copy.
  return{action,caption,board:[...board],columns:g.columns,rows:g.rows,cells:[...cells],wins:extra.wins||[]};
 }
 unit(symbol:number,count:number){return (.025+.015*(8-symbol))*Math.pow(2,Math.max(0,count-3));}
 private inFree<T>(run:()=>T):T{const saved=this.drawingFree;this.drawingFree=true;try{return run();}finally{this.drawingFree=saved;}}
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-roses';}
 prepareBonusPurchase(bet:number,rng:()=>number){
  // The gate fixes all nine middle cells. Outer reels retain their independent
  // natural stacks; no rejection loop or fabricated ordinary winning cells.
  const board=this.draw(bet,rng);for(const col of [1,2,3])for(let row=0;row<3;row++)board[row*5+col]=this.id('scatter');
  return this.purchaseFromResult(this.play(board,bet,rng));
 }
 draw(bet:number,rng:()=>number,g:Geometry=this.geometry){
  if(!this.bets.includes(bet)||g.columns!==5||g.rows!==3)throw Error('Invalid goddess wager or geometry');const high=this.drawingFree?GODDESS_MODEL.freeHighByBet[bet]:GODDESS_MODEL.baseHighByBet[bet],rose=this.drawingFree?GODDESS_MODEL.freeRose:GODDESS_MODEL.baseRose;
  const b=Array.from({length:15},()=>this.id(goddessOrdinary(high,rng)));for(let col=0;col<5;col++){const positions=[col,col+5,col+10];if(goddessUniform(rng)<(col>0&&col<4?rose:0))positions.forEach(c=>b[c]=this.id('scatter'));else if(goddessUniform(rng)<GODDESS_MODEL.baseStackForce){const symbol=b[col];positions.forEach(c=>b[c]=symbol);}}return b;
 }
 private stacks(b:string[],bet:number,rng:()=>number,selected?:number){const cols=Array.from({length:5},(_,col)=>col).filter(col=>b[col]!==this.id('scatter')&&b[col]===b[col+5]&&b[col]===b[col+10]),changed=cols.flatMap(col=>[col,col+5,col+10]),after=[...b],symbol=selected??ri(rng,8),frames=[this.frame(b,'reels','5×3 · 40라인 SUPER STACK')];if(cols.length){frames.push(this.frame(b,'trigger','세로 스택 착지 · 변환 대상 확인',changed));changed.forEach(c=>after[c]=this.id(symbol));frames.push(this.frame(after,'effect','모든 스택 → '+this.config.symbols[symbol].name,changed));}frames.push(this.hit(after,bet,'SUPER STACK · 40라인 당첨'));return this.round(bet,frames);}
 play(b:string[],bet:number,rng:()=>number){const base=this.stacks(b,bet,rng),gate=[1,2,3].flatMap(col=>[col,col+5,col+10]);if(!gate.every(c=>b[c]===this.id('scatter')))return this.finish([base]);base.expansionFeature!.frames.push(this.frame(b,'trigger','가운데 세 릴 장미 스택 · 무료 7회',gate));const hidden=[0,1,2,3];for(let i=3;i>0;i--){const j=ri(rng,i+1);[hidden[i],hidden[j]]=[hidden[j],hidden[i]];}const results=this.inFree(()=>hidden.map(selected=>{const opening=this.round(bet,JSON.parse(JSON.stringify(base.expansionFeature!.frames)));opening.expansionFeature!.frames.push(this.frame(b,'reveal','선택한 장미 → '+this.config.symbols[selected].name,gate));const rounds=[opening];for(let left=6;left>=0;left--){const raw=this.draw(bet,rng);for(let col=0;col<5;col++)if(raw[col]!==this.id('scatter')&&goddessUniform(rng)<GODDESS_MODEL.freeExtraStackForce)for(let row=1;row<3;row++)raw[row*5+col]=raw[col];const round=this.stacks(raw,bet,rng,selected);round.freeSpinsRemaining=left;round.selectedSymbol=this.id(selected);rounds.push(round);}return this.finish(rounds,{freeSpinsAwarded:7,featureOnly:false,selectedSymbol:this.id(selected)});}));return this.choices('장미를 선택해 스택 심볼을 공개하세요',['장미 1','장미 2','장미 3','장미 4'],results);}
}
