import{gapUniform}from'./GapInputBoard';
import{TOY_MODEL}from'./ToyDefendersMath';
/** Valid fixed input CDF mapped to the unchanged source floor bins. */
export function toyCountInput(tool:number,u:number){u=gapUniform(()=>u);const law=TOY_MODEL.toolLaws[tool];let roll=u;for(let k=0;k<law.length;k++){roll-=law[k];if(roll<0)return(k+.5)/law.length;}return(law.length-.5)/law.length;}
