/** Declared local cell inputs. Five reels are independent, marker probability
 * fixed and progress-independent. The first reel has a different ordinary0
 * weight; actual source pays/gains/prize frequencies are unchanged. */
export const ATLAS_INPUT_WEIGHTS=[5,6,7,8,10,12,14,16,2];
export const ATLAS_MODEL={"scatter":0.02308802310577035,"firstHigh":61.245460431962236};
export function atlasUniform(rng:()=>number){const value=rng();if(!Number.isFinite(value)||value<0||value>=1)throw Error('Invalid atlas uniform');return value;}
export function atlasInputSymbol(reel:number,rng:()=>number){if(!Number.isInteger(reel)||reel<0||reel>4)throw Error('Invalid atlas reel');const value=atlasUniform(rng);if(value<ATLAS_MODEL.scatter)return 'scatter';const high=reel===0?ATLAS_MODEL.firstHigh:1,sum=75+5*high;let target=(value-ATLAS_MODEL.scatter)/(1-ATLAS_MODEL.scatter)*sum;for(let i=0;i<9;i++)if((target-=ATLAS_INPUT_WEIGHTS[i]*(i===0?high:1))<0)return i===8?'wild':String(i);return 'wild';}
