export function slotStageMotif(id:string):StageMotif{
 return (Object.entries(groups).find(([,ids])=>ids.includes(id))?.[0] as StageMotif)||'garden';
}
/** Transparent scenery stays below status copy and above the controls. */
export function slotStageFrame(width:number,statusBottom:number,panelTop:number){
 const y=statusBottom+8,h=Math.max(0,panelTop-y-6),actorSize=Math.max(0,Math.min(208,h-16));
 return {x:8,y,w:width-16,h,actorX:Math.max(260,width-actorSize-48),actorY:y+h-actorSize-4,actorSize};
}
/** Fill the lower lane with Zeus, keeping the purchase button clear on the left. */
export function olympusActorFrame(width:number,statusBottom:number,panelTop:number){
 const top=statusBottom+8,bottom=panelTop-6,left=256,right=width-24;
 // Eight units on each side of the figure absorb its bob and slight rotation.
 const size=Math.max(0,Math.min(right-left-16,bottom-top-16));
 return{x:left+(right-left-size)/2,y:bottom-8-size,size};
}
