export function catUniform(rng:()=>number){const x=rng();if(!Number.isFinite(x)||x<0||x>=1)throw Error("Invalid cat uniform");return x;}
export function catOrdinary(high:number,col:number,rng:()=>number){const weights=[5*high,6,7,8,10,12,14,16,col?2:0];let roll=catUniform(rng)*weights.reduce((n,v)=>n+v,0);for(let i=0;i<weights.length;i++){roll-=weights[i];if(roll<0)return i===8?'wild':String(i);}return'7';}
