import {SlotMain,SlotConfig,SpinResult,Win,SlotPresentation} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {oathInputBoard,oathInputPurchase} from './OathbladeInputBoard';
import {WOLF_LINES} from './WolfRules';
import {drawReelBoard} from './ReelScatter';
export const OATH_ID='oathblade-order';
export const OATH_PAYS=[[1.2,3.2,8],[1,2.4,6],[.8,2,4.8],[.6,1.6,4],[.4,1.2,3.2],[.4,1,2.4],[.4,.8,2]];
export interface OathPlayback {stage:'entry'|'free';unit:number;sourceCells:number[];lineWins:Win[];swords:{cell:number;award:Win}[];}
export class OathbladeSlot extends SlotMain {
 readonly columns=5;readonly rows=3;readonly paylines=WOLF_LINES.slice(0,5);readonly bets=[...BET_LEVELS];readonly hasBonus=true;readonly maxWin=10000;readonly usesLocalPayouts=true;readonly bonusCalibrationKey=OATH_ID+':repeat-v1';
 readonly presentation:SlotPresentation={evidence:'official-rules',anticipationText:'황금 방패 당첨',triggerText:'서약 금액 저장',bonusInText:'검마다 같은 금액 반복 지급',hitText:'서약의 검',totalWinText:'기사단 총 보상',signature:'진입 당첨액을 저장하고 검 하나마다 반복 지급',uiEffect:'단가 봉인·검에서 반복 지급',soundCue:'featureLand',anticipationHold:.3,hitHold:.2,outHold:.4};
 readonly config:SlotConfig={id:OATH_ID,title:'서약의 검 기사단',subtitle:'OATHBLADE ORDER',tag:'STORED REPEAT WIN',color:'#243b4e',accent:'#e2c075',description:'5×3 · 5라인 · 왼쪽부터3개 이상\n황금 방패 WILD가 포함된 당첨이면 무료10회.\n그 당첨들의 합을 서약 단가로 저장합니다.\n무료 회전의 검 하나마다 저장 단가를 반복 지급. 일반 라인 당첨도 합산.\n무료 중 왕관3개 이상이면 +2회, 총20회까지.\n구매에서도 저장 단가를 검마다 그대로 지급. 최대10,000배.',symbols:['기사 투구','푸른 깃발','봉인 반지','서약 문서','성문 열쇠','은 잔','가죽 장갑','서약의 검','황금 방패 WILD','왕관'].map((name,i)=>({id:OATH_ID+'-'+(i===8?'wild':i===9?'scatter':i),name,color:'#e2c075',weight:[5,6,8,10,12,14,16,4,2.5,1.5][i],payout:i<7?OATH_PAYS[i][2]:0}))};
 evaluate(board:string[],bet:number):SpinResult {
  if(!this.bets.includes(bet)||board.length!==15||board.some(s=>!this.config.symbols.some(t=>s===t.id)))throw Error('Invalid oath spin');
  const wins:Win[]=[];
  this.paylines.forEach((line,index)=>{let best:Win|undefined;for(let s=0;s<7;s++){const cells:number[]=[];for(const c of line){if(board[c]!==OATH_ID+'-'+s&&board[c]!==OATH_ID+'-wild')break;cells.push(c);}if(cells.length<3)continue;const amount=Math.round(bet*OATH_PAYS[s][cells.length-3]);if(!best||best.amount<amount)best={line:index,symbol:OATH_ID+'-'+s,cells,amount};}if(best)wins.push(best);});
  return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),presentation:this.presentation};
 }
 private draw(bet:number,rng:()=>number){return this.evaluate(oathInputBoard(OATH_ID,bet,rng),bet);}
 private qualifying(base:SpinResult){return base.wins.filter(w=>w.cells.some(c=>base.board[c]===OATH_ID+'-wild'));}
 private bonus(base:SpinResult,rng:()=>number,purchase=false){
  const qualifying=this.qualifying(base),unit=qualifying.reduce((n,w)=>n+w.amount,0),sourceCells=Array.from(new Set(qualifying.flatMap(w=>w.cells)));if(!unit)return base;
  base.oathFeature={stage:'entry',unit,sourceCells,lineWins:base.wins,swords:[]};
  // Preserve the qualifying unit, but an unpaid purchase entry uses no cap.
  if(purchase){base.wins=[];base.payout=0;base.oathFeature.lineWins=[];}
  const rounds=[base];let remaining=10,awarded=10,played=0,paid=base.payout;
  while(remaining>0&&paid<base.bet*this.maxWin){remaining--;played++;const r=this.evaluate(oathInputBoard(OATH_ID,base.bet,rng,true),base.bet),lineWins=[...r.wins],swords=r.board.flatMap((symbol,cell)=>symbol===OATH_ID+'-7'?[{cell,award:{line:-1,symbol,cells:[cell],amount:unit}}]:[]);r.wins.push(...swords.map(s=>s.award));
   let budget=base.bet*this.maxWin-paid;for(const win of r.wins){win.amount=Math.min(budget,win.amount);budget-=win.amount;}r.payout=r.wins.reduce((n,w)=>n+w.amount,0);paid+=r.payout;
   const extra=r.board.filter(s=>s===OATH_ID+'-scatter').length>=3?Math.min(2,20-awarded):0;remaining+=extra;awarded+=extra;
   r.oathFeature={stage:'free',unit,sourceCells,lineWins,swords};r.freeSpinsRemaining=remaining;r.freeSpinsAdded=extra||undefined;r.roundLabel='서약 무료 '+played+' · 남은 '+remaining+'회';rounds.push(r);
  }
  return{board:[...rounds[rounds.length-1].board],bet:base.bet,rounds,wins:rounds.flatMap(r=>r.wins),payout:paid,freeSpinsAwarded:10,featureName:'서약의 검 · 단가 '+unit,presentation:this.presentation,bonusEndReason:paid>=base.bet*this.maxWin?'max-win' as const:'spins-exhausted' as const};
 }
 spin(bet:number,rng:()=>number=Math.random){return this.bonus(this.draw(bet,rng),rng);}
 prepareBonusPurchase(bet:number,rng:()=>number):SpinResult {
  const base=this.evaluate(oathInputPurchase(OATH_ID,bet,rng),bet),result=this.bonus(base,rng,true),rounds=result.rounds!.slice(1),wins=rounds.flatMap(r=>r.wins);return{...result,rounds,wins,payout:wins.reduce((n,w)=>n+w.amount,0),bonusTriggerRound:{board:[...base.board],bet,wins:[],payout:0,featureText:'서약 기준 '+base.oathFeature!.unit+' · 검마다 같은 금액 지급'}};
 }

 demoSpin(bet:number){return this.find(bet,false);}
 bonusDemoSpin(bet:number){return this.find(bet,true);}
 private find(bet:number,bonus:boolean){let seed=340928;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<100000;i++){const r=this.spin(bet,rng);if(bonus?!!r.rounds:!r.rounds&&r.wins.length===1)return r;}throw Error('Oath fixture unavailable');}
}
