export function catPromotionAudit(params:URLSearchParams){const slot=new CatPromotionSlot(EXPANSION_SPECS.find(s=>s.id==='cat-diamond-promotion')!),outcome=params.get('audit-cat-promotion-case')||params.get('audit-outcome')||'',kind=({'no-win':'empty','multi-win':'multi'} as Record<string,string>)[outcome]||outcome,initial=CAT_PROMOTION_AUDIT_SEEDS[kind];if(initial!==undefined){const spin=(bet:number)=>{let seed=initial;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;},r=slot.spin(bet,rng);if(['free','promote2','promote3','full','retrigger'].includes(kind)){if(!r.rounds||r.freeSpinsAwarded!==15)throw Error('Stale Cat free witness');const promoted=Math.max(0,...r.rounds.slice(1).flatMap(q=>q.expansionFeature!.frames).map(f=>f.panel?.active?.length||0));if(kind==='full'&&promoted!==4||kind==='promote3'&&promoted<3||kind==='promote2'&&promoted<2||kind==='retrigger'&&!r.rounds.some(q=>q.freeSpinsAdded===15))throw Error('Stale Cat promotion witness');}return r;};slot.demoSpin=spin;if(['free','promote2','promote3','full','retrigger'].includes(kind))slot.bonusDemoSpin=spin;}return slot;}
