import {SpinResult} from './SlotMain';
import {Social2230LineSlot,socialPresentation,packRounds} from './Social2230Rules';
import {socialSeed} from './Social1921Rules';
import {RED_CLOAK_MODEL as MODEL,redUniform,redOrdinary} from './RedCloakMath';
export interface ExpeditionPlayback {stage:'map'|'equip'|'battle';before:number[];after:number[];tokens:number[];equipment?:number;}
export class RedCloakSlot extends Social2230LineSlot {
 private drawingEquipment=-1;private drawingBet=100;
 protected pick(rng:()=>number){const e=this.drawingEquipment,h=e<0?MODEL.highByBet[this.drawingBet]:MODEL.freeHighByBet[this.drawingBet][e],wild=e<0?MODEL.baseWild:MODEL.freeWild,sum=5*h+6+7+8+10+12+14+16+wild,q=e<0?MODEL.piece:MODEL.freeScatter/(sum+MODEL.freeScatter);return this.config.id+'-'+(redUniform(rng)<q?'scatter':redOrdinary(h,wild,rng));}
 protected draw(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid Red bet');const old=this.drawingBet;this.drawingBet=bet;try{return super.draw(bet,rng);}finally{this.drawingBet=old;}}
 readonly presentation=socialPresentation('지도에서 장비 획득 · 다음 거점에서 소비','망토 원정대');
 readonly config=this.namedConfig('red-cloak-expedition','붉은 망토 원정대','RED CLOAK EXPEDITION',['붉은 망토','석궁','여행 장화','약초 가방','숲 나침반','나무 방패','야영 냄비','길표지','수호 문장 WILD','지도 조각'],'지도 조각 3개 누적: 장비 선택. 다음 3개 누적: 전투 무료 5회.\n석궁: 고액 심볼 증가 / 방패: WILD 증가 / 장화: 무료 +2회(라인 배당 75%).\n장비는 다음 전투에서 한 번 소비. 지도·장비는 베팅별 저장.\n전투 중 조각 수집·재진입 없음. ','#333c36','#eea19a');
 spin(bet:number,rng:()=>number=Math.random):SpinResult{
  const base=this.draw(bet,rng),raw=this.state(bet,[0,0,0]),before=raw.length===3&&raw[0]<3&&raw[1]<=1&&raw[2]<=2?raw:[0,0,0],tokens=base.board.flatMap((s,c)=>s===this.config.id+'-scatter'?[c]:[]),count=before[0]+tokens.length;
  const after=[Math.min(3,count),before[1],before[2]];base.expeditionFeature={stage:'map',before,after,tokens};
  if(count<3){base.progressUpdate=this.update(bet,after);return base;}
  if(before[1]===0){
   const branches=[0,1,2].map(equipment=>{const next=[0,1,equipment],round:SpinResult={board:[...base.board],bet,payout:0,wins:[],expeditionFeature:{stage:'equip',before,after:next,tokens:[],equipment}};return packRounds([base,round],{featureOnly:true,progressUpdate:this.update(bet,next),presentation:this.presentation});});
   return{...branches[0],featureChoices:{title:'다음 거점 전투에 사용할 장비',labels:['석궁 · 고액 심볼 증가','방패 · WILD 증가','장화 · 무료 2회 추가 / 배당 75%'],results:branches,defaultIndex:0,noBonusEntry:true}};
  }
  return this.battle(base,before,before[2],rng);
 }
 private battle(base:SpinResult,before:number[],equipment:number,rng:()=>number){const bet=base.bet,rounds=[base],free=equipment===2?7:5,oldEquipment=this.drawingEquipment,oldBet=this.drawingBet;this.drawingEquipment=equipment;this.drawingBet=bet;try{
  for(let n=0;n<free;n++){
   const board=Array.from({length:15},()=>{const roll=redUniform(rng);return equipment===0&&roll<MODEL.crossbowOverride?this.config.id+'-0':equipment===1&&roll<MODEL.shieldOverride?this.config.id+'-wild':this.pick(rng);}),round=this.evaluate(board,bet);
   if(equipment===2){for(const win of round.wins){win.amount=Math.round(win.amount*.75);win.multiplier!*=.75;}round.payout=round.wins.reduce((sum,w)=>sum+w.amount,0);}
   round.expeditionFeature={stage:'battle',before:[...before],after:[0,0,0],tokens:[],equipment};round.freeSpinsRemaining=free-n-1;round.roundLabel='원정대 전투 · 남은 '+(free-n-1)+'회';rounds.push(round);
  }
  return packRounds(rounds,{progressUpdate:this.update(bet,[0,0,0]),freeSpinsAwarded:free,presentation:this.presentation,featureName:'장비 장착 · 원정대 전투'});
  }finally{this.drawingEquipment=oldEquipment;this.drawingBet=oldBet;}
 }
 prepareBonusPurchase(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid Red bet');const q=MODEL.piece,mass:Array<number>=[],choose=(n:number)=>{let v=1;for(let k=1;k<=n;k++)v=v*(16-k)/k;return v;};for(let n=3;n<=15;n++)mass.push(choose(n)*q**n*(1-q)**(15-n));let count=15,pick=redUniform(rng)*mass.reduce((a,b)=>a+b,0);for(let n=3;n<=15;n++){pick-=mass[n-3];if(pick<0){count=n;break;}}
  const board=Array.from({length:15},()=>this.config.id+'-'+redOrdinary(MODEL.highByBet[bet],MODEL.baseWild,rng)),available=Array.from({length:15},(_,i)=>i);for(let n=0;n<count;n++){const i=Math.floor(redUniform(rng)*available.length),cell=available.splice(i,1)[0];board[cell]=this.config.id+'-scatter';}
  const results=[0,1,2].map(e=>{const base:SpinResult={board:[...board],bet,wins:[],payout:0,presentation:this.presentation},r=this.battle(base,[0,1,e],e,rng),rounds=r.rounds!.slice(1);return packRounds(rounds,{freeSpinsAwarded:r.freeSpinsAwarded,featureName:r.featureName,presentation:r.presentation,bonusTriggerRound:base});});return{...results[0],featureChoices:{title:'구매 전투 장비 선택',labels:['석궁 · 고액 심볼 증가','방패 · WILD 증가','장화 · 무료 2회 추가 / 배당 75%'],results,defaultIndex:0}};
 }
 demoSpin(bet:number){const previous=this.progress;try{this.progress={[this.config.id+':'+bet]:[2,1,1]};const rng=socialSeed(29);for(let n=0;n<1000;n++){const r=this.spin(bet,rng);if(r.rounds)return r;}throw Error('Expedition preview unavailable');}finally{this.progress=previous;}}
}
