import {SunGoddessSlot} from './SunGoddessSlot';import {EXPANSION_SPECS} from './ExpansionCatalog';import {SpinResult} from './SlotMain';
/** Complete source-spin seeds from continuous prefixes. Choosing a blind card
 * changes only offline QA selection metadata, never branch awards or boards. */
export const GODDESS_AUDIT_SEEDS:Record<string,number>={stack:11222961,empty:11222961,multi:989284387,free:2877640347};
export function sunGoddessAudit(params:URLSearchParams){const slot=new SunGoddessSlot(EXPANSION_SPECS.find(s=>s.id==='sun-goddess-stack')!),outcome=params.get('audit-goddess-case')||params.get('audit-outcome')||'',kind=({'no-win':'empty','multi-win':'multi'} as Record<string,string>)[outcome]||outcome,choice=/^(?:free|purchase)[0-3]$/.test(kind)?Number(kind.slice(-1)):undefined,select=(r:SpinResult)=>choice===undefined?r:{...r.featureChoices!.results[choice],featureChoices:{...r.featureChoices!,defaultIndex:choice}};
 if(kind.startsWith('purchase')){const native=slot.prepareBonusPurchase.bind(slot);slot.prepareBonusPurchase=(bet,rng)=>select(native(bet,rng));}else {const seed=GODDESS_AUDIT_SEEDS[kind.startsWith('free')?'free':kind];if(seed!==undefined){const spin=(bet:number)=>{let value=seed;const rng=()=>{value=(Math.imul(value,1664525)+1013904223)>>>0;return value/4294967296;};const r=slot.spin(bet,rng);if(kind.startsWith('free')&&!r.featureChoices)throw Error('Stale Goddess bonus seed');return select(r);};slot.demoSpin=spin;if(kind.startsWith('free'))slot.bonusDemoSpin=spin;}}
 return slot;}
