import {ExpansionSlot,ExpansionFrame,expansionCells as cells,randomIndex} from './ExpansionCore';
import {SpinResult,Win} from './SlotMain';
import {CITY_MODEL,cityCellInput,cityPrize,cityUniform} from './CityMath';
/** Vegas Cash structure. All weights, free count and coin awards are local rules. */
export class CityLinkedSlot extends ExpansionSlot {
 constructor(spec:ConstructorParameters<typeof ExpansionSlot>[0]){
  super(spec);
  this.config.description='5×3 · 50라인 · 왼쪽부터 연결\n코인 6개 이상: 고정 리스핀 3회. 새 코인이 멈추면 남은 횟수를 3회로 복구합니다.\n달러 표식 3개 이상: 무료 10회 또는 코인 리스핀을 무작위로 시작합니다. 무료 중 재발동은 없습니다.\n15칸 완성: 고정 도시 상금. 서버 공유 잭팟은 적용하지 않습니다. 구매는 독립 코인 리스핀으로 진입합니다.';
  for(const [name,weight]of [['coin',10],['portrait',0],['wheel',0],['seal',0]] as const)this.config.symbols.push({id:this.id(name),name,color:'#efc064',weight,payout:0});
  const seen=new Set(this.paylines.map(x=>x.join(',')));for(let code=0;this.paylines.length<50;code++){let n=code;const line=Array.from({length:5},(_,c)=>{const r=n%3;n=Math.floor(n/3);return r*5+c;});if(!seen.has(line.join(','))){seen.add(line.join(','));this.paylines.push(line);}}
 }
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-city';}
 private weighted(rng:()=>number,pool:{id:string;weight:number}[]){let r=rng()*pool.reduce((n,s)=>n+s.weight,0);for(const s of pool){r-=s.weight;if(r<0)return s.id;}return pool[pool.length-1].id;}
 private drawingFree=false;
 unit(symbol:number,count:number){return (.025+.015*(8-symbol))*Math.pow(2,Math.max(0,count-3));}
 draw(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');const profile=this.drawingFree?CITY_MODEL.free:CITY_MODEL.base,board=Array.from({length:15},()=>this.id(cityCellInput(bet,rng,profile)));
  for(let col=0;col<5;col++)if(cityUniform(rng)<profile.scatterPerReel)board[randomIndex(rng,3)*5+col]=this.id('scatter');return board;
 }
 private coin(rng:()=>number){return cityPrize(rng);}
 private startCoins(rng:()=>number){const positions=Array.from({length:15},(_,c)=>c);for(let i=14;i>0;i--){const j=randomIndex(rng,i+1);[positions[i],positions[j]]=[positions[j],positions[i]];}return new Set(positions.slice(0,6));}
 private hold(board:string[],bet:number,rng:()=>number,base:SpinResult){
  const held=new Map<number,number>(),rounds=[base],snapshots:ExpansionFrame[]=[];let left=3;
  const initial=cells(board,this.id('coin'));for(const c of initial.length>=6?initial:this.startCoins(rng))held.set(c,this.coin(rng));
  const frame=(action:ExpansionFrame['action'],caption:string,focus:number[]=[],previous=Array.from(held.keys()))=>{const b=Array.from({length:15},(_,c)=>held.has(c)?this.id('coin'):''),f=this.frame(b,action,caption,focus,{held:previous,remaining:left,panel:{label:'CITY COINS',values:[held.size,15],columns:2}});snapshots.push(f);return f;};
  rounds.push(this.round(bet,[frame('state','도시 코인 고정 · 리스핀 3회')]));
  while(left>0&&held.size<15){left--;const previous=Array.from(held.keys()),landed:number[]=[];for(let c=0;c<15;c++)if(!held.has(c)&&cityUniform(rng)<CITY_MODEL.landing){held.set(c,this.coin(rng));landed.push(c);}const fs=[frame('reels','고정 코인 유지 · 빈칸 리스핀',[],previous)];if(landed.length){left=3;fs.push(frame('effect','새 코인 고정 · 3회 복구',landed));}fs.push(frame('state','남은 리스핀 '+left+'회'));rounds.push(this.round(bet,fs));}
  left=0;const awards=new Map<number,Win>();for(const[cell,value]of held)awards.set(cell,{line:-1,symbol:this.id('coin'),cells:[cell],amount:bet*value,multiplier:value});
  const fs:ExpansionFrame[]=[];if(held.size===15){fs.push(frame('trigger','15칸 완성 · 도시 상금',Array.from(held.keys())));const f=frame('win','도시 완성 상금 한 번 지급',Array.from(held.keys()));f.wins=[{line:-1,symbol:this.id('wild'),cells:Array.from(held.keys()),amount:bet*50,multiplier:50}];fs.push(f);}
  const paid=frame('win','고정 코인 합계 · 한 번 지급',Array.from(held.keys()));paid.wins=Array.from(awards.values());fs.push(paid);rounds.push(this.round(bet,fs));for(const f of snapshots)f.coinAwards=cells(f.board,this.id('coin')).map(cell=>({cell,win:awards.get(cell)!}));return this.finish(rounds,{featureOnly:true});
 }
 play(board:string[],bet:number,rng:()=>number){
  this.validate(board,bet);const base=this.ordinary(board,bet),coins=cells(board,this.id('coin')),gates=cells(board,this.id('scatter'));
  if(coins.length>=6){base.expansionFeature!.frames.push(this.frame(board,'trigger','코인 '+coins.length+'개 · 도시 리스핀',coins));return this.hold(board,bet,rng,base);}
  if(gates.length>=3){const free=rng()<.5;base.expansionFeature!.frames.push(this.frame(board,'reveal',free?'달러 보너스 · 무료 10회':'달러 보너스 · 코인 리스핀',gates,{panel:{label:'CITY BONUS',values:[free?1:0,free?0:1],columns:2}}));if(!free)return this.hold(board,bet,rng,base);this.drawingFree=true;try{return this.freeFromRound(base,bet,rng,10,b=>this.ordinary(b,bet,'도시 무료 회전 · 일반 라인 지급'),gates);}finally{this.drawingFree=false;}}
  return this.finish([base]);
 }
 prepareBonusPurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  // Standalone six-coin entry, independent from the unimplemented server jackpot.
  const rich=this.startCoins(rng),plain=this.config.symbols.filter(s=>s.weight>0&&s.id!==this.id('coin')&&s.id!==this.id('scatter')),board=Array.from({length:15},(_,c)=>rich.has(c)?this.id('coin'):this.weighted(rng,plain));
  return this.purchaseFromResult(this.hold(board,bet,rng,this.round(bet,[this.frame(board,'trigger','독립 도시 코인 보너스 구매',Array.from(rich))])));
 }
}
