import {WolfStackSlot} from './WolfStackSlot';import {EXPANSION_SPECS} from './ExpansionCatalog';
/** Full source paid-spin witnesses including a genuine natural retrigger. */
export const RIDGE_AUDIT_SEEDS:Record<string,number>={empty:11555961,multi:2229710371,stack:1624951130,free:1923851934,retrigger:4222366075};
export function wolfStackAudit(params:URLSearchParams){const slot=new WolfStackSlot(EXPANSION_SPECS.find(s=>s.id==='wolf-stack-ridge')!),outcome=params.get('audit-ridge-case')||params.get('audit-outcome')||'',kind=({'no-win':'empty','multi-win':'multi'} as Record<string,string>)[outcome]||outcome,initial=RIDGE_AUDIT_SEEDS[kind];if(initial!==undefined){const spin=(bet:number)=>{let seed=initial;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};const r=slot.spin(bet,rng);if(kind==='free'&&(r.rounds?.length!==6||r.freeSpinsAwarded!==5))throw Error('Stale ridge free witness');if(kind==='retrigger'&&!r.rounds?.some(q=>q.freeSpinsAdded===5))throw Error('Stale ridge retrigger witness');return r;};slot.demoSpin=spin;if(kind==='free'||kind==='retrigger')slot.bonusDemoSpin=spin;}return slot;}
