import {SlotMain,SlotConfig,SpinResult,Win,CellDrop} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {socialPresentation,packRounds} from './Social2230Rules';

// Preserve sampled awards before shared cap/rounding for independent purchases.
const preSettlementAwards=new WeakMap<SpinResult[],number[][]>();
export type TumbleAction='land'|'win'|'drop'|'move'|'transform'|'collect'|'state';
export interface TumbleTile {cell:number;x:number;y:number;w:number;h:number;}
export interface TumbleFrame {
 action:TumbleAction;board:string[];caption:string;wins:Win[];cells:number[];
 moves:CellDrop[];badges:Record<number,string>;marks:number[];tiles?:TumbleTile[];stationary?:number[];
}
export interface TumblePlayback {frames:TumbleFrame[];termination:'settled'|'safety-cap';}
export const tumbleRng=(seed:number)=>()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
export function randomIndex(rng:()=>number,n:number){const v=rng();if(!Number.isFinite(v)||v<0||v>=1||n<1)throw Error('Invalid tumble RNG');return Math.floor(v*n);}
export const totalWins=(wins:Win[])=>wins.reduce((n,w)=>n+w.amount,0);
export const indices=(b:string[],s:string)=>b.flatMap((v,i)=>v===s?[i]:[]);
export function adjacent(c:number,columns:number,size:number){return[c-columns,c+columns,...(c%columns?[c-1]:[]),...(c%columns<columns-1?[c+1]:[])].filter(i=>i>=0&&i<size);}
export function connected(board:string[],symbol:string,wild:string|undefined,neighbors:(c:number)=>number[]){
 const seen=new Set<number>(),groups:number[][]=[];
 for(let c=0;c<board.length;c++)if(!seen.has(c)&&(board[c]===symbol||board[c]===wild)){
  const stack=[c],group:number[]=[];seen.add(c);
  while(stack.length){const at=stack.pop()!;group.push(at);for(const n of neighbors(at))if(!seen.has(n)&&(board[n]===symbol||board[n]===wild)){seen.add(n);stack.push(n);}}
  if(group.some(i=>board[i]===symbol))groups.push(group);
 }return groups;
}
/** Shared transport/settlement only. Each game supplies its own state machine. */
export abstract class TumbleGame extends SlotMain {
 readonly mode='clusters' as const;readonly usesLocalPayouts=true;readonly bets=[...BET_LEVELS];readonly maxWin=5000;
 abstract readonly config:SlotConfig;readonly regularCount:number=6;readonly threshold:number=5;
 idleFrame():TumbleFrame|null{return null;}
 get payoutFactor(){return 1;}
 abstract rawSpin(bet:number,rng?:()=>number):SpinResult;
 spin(bet:number,rng:()=>number=Math.random):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  return this.rawSpin(bet,rng);
 }
 get bonusCalibrationKey(){return this.config.id+':tumble-v1';}
 get presentation(){return socialPresentation(this.config.title,this.config.tag);}
 id(s:string|number){return this.config.id+'-'+s;}
 get wild(){return this.config.symbols.some(s=>s.id===this.id('wild'))?this.id('wild'):undefined;}
 get bonusSymbol(){return this.config.symbols.some(s=>s.id===this.id('scatter'))?this.id('scatter'):undefined;}
 protected configFor(id:string,title:string,subtitle:string,names:string[],roles:string[],description:string,weights?:number[]):SlotConfig {
  return{id,title,subtitle,tag:subtitle,color:'#223047',accent:'#f3d488',description:description+'\n공개 피처를 참고한 자체 규칙·확률. 원작 수학의 복제 아님.',symbols:names.map((name,n)=>({id:id+'-'+roles[n],name,art:'gem',color:['#ee7186','#e5ae69','#e5d781','#77ba9c','#739dcf','#ae86c9'][n%6],weight:weights?.[n]??(n<this.regularCount?12:1),payout:n<this.regularCount?this.unit(n,5):0}))};
 }
 /** Base cluster table in bet multiples, before explicitly displayed features. */
 unit(symbol:number,count:number){return count<this.threshold?0:(.045+.009*(this.regularCount-symbol))*Math.pow(count-this.threshold+1,1.35);}
 check(board:string[],bet:number){if(!this.bets.includes(bet)||board.length!==this.columns*this.rows||board.some(s=>s!==this.id('void')&&!this.config.symbols.some(t=>t.id===s)))throw Error('Invalid tumble board/bet');}
 draw(rng:()=>number){return Array.from({length:this.columns*this.rows},()=>this.pick(()=>{const v=rng();if(!Number.isFinite(v)||v<0||v>=1)throw Error('Invalid tumble RNG');return v;}));}
 clusters(board:string[],bet:number,multiplier=1,neighbors=(c:number)=>adjacent(c,this.columns,board.length),minimum=this.threshold):Win[]{
  const wins:Win[]=[];
  for(let s=0;s<this.regularCount;s++)for(const cells of connected(board,this.id(s),this.wild,neighbors))if(cells.length>=minimum)wins.push({line:-1,symbol:this.id(s),cells,amount:bet*this.unit(s,cells.length)*multiplier,multiplier});
  return wins;
 }
 evaluate(board:string[],bet:number):SpinResult{this.check(board,bet);const wins=this.clusters(board,bet);return this.finish([{board:[...board],bet,wins,payout:totalWins(wins)}]);}

 frame(frames:TumbleFrame[],board:string[],action:TumbleAction,caption:string,options:Partial<Omit<TumbleFrame,'board'|'action'|'caption'>>={}){
  const f:TumbleFrame={board:[...board],action,caption,wins:[],cells:[],moves:[],badges:{},marks:[],...options};
  f.cells=[...f.cells];f.moves=f.moves.map(m=>({...m}));f.badges={...f.badges};f.marks=[...f.marks];if(f.stationary)f.stationary=[...f.stationary];if(f.tiles)f.tiles=f.tiles.map(t=>({...t}));frames.push(f);return f;
 }
 prize(bet:number,value:number,cells:number[],symbol=this.config.symbols[0].id):Win{return{line:-1,symbol,cells:[...cells],amount:bet*value,multiplier:value};}
 /** Gravity operates on active cells only; pinned tokens partition each column. */
 gravity(board:string[],removed:Set<number>,rng:()=>number,pinned=new Set<number>(),active=(c:number)=>board[c]!==this.id('void')){
  const after=[...board],moves:CellDrop[]=[];
  for(let col=0;col<this.columns;col++){
   let segment:number[]=[];
   const flush=()=>{const kept=segment.filter(c=>!removed.has(c)),incoming=segment.length-kept.length;
    segment.forEach((to,j)=>{const from=j<incoming?-(incoming-j)*this.columns+col:kept[j-incoming],symbol=from<0?this.pick(rng):board[from];after[to]=symbol;moves.push({from,to,symbol});});segment=[];};
   for(let row=0;row<this.rows;row++){const c=row*this.columns+col;if(!active(c)){flush();continue;}if(pinned.has(c)){flush();moves.push({from:c,to:c,symbol:board[c]});}else segment.push(c);}flush();
  }return{board:after,moves};
 }
 round(bet:number,frames:TumbleFrame[],termination:TumblePlayback['termination']='settled'):SpinResult{if(frames.some(f=>f.caption.includes('안전 종료')))termination='safety-cap';const wins=frames.flatMap(f=>f.wins);return{bet,board:[...frames[frames.length-1].board],openingBoard:[...frames[0].board],wins,payout:totalWins(wins),tumbleFeature:{frames,termination},presentation:this.presentation};}
 finish(rounds:SpinResult[],extras:Partial<SpinResult>={}):SpinResult{
  // Round cumulative awards, not each tiny collection. This keeps the same
  // expected return at 20 coins and prevents per-fruit rounding inflation.
  if(rounds.length>1)preSettlementAwards.set(rounds,rounds.map(r=>r.wins.map(w=>w.amount)));
  let rawBudget=rounds[0].bet*this.maxWin,exact=0,paid=0;
  const maximum=rawBudget;
  for(const r of rounds){for(const w of r.wins){const raw=Math.min(rawBudget,w.amount);rawBudget-=raw;exact+=raw;const next=Math.min(maximum,Math.round(exact));w.amount=next-paid;paid=next;}r.payout=totalWins(r.wins);}
  return rounds.length===1?{...rounds[0],...extras}:packRounds(rounds,{presentation:this.presentation,featureName:this.config.title,...extras});
 }

 /** Preserve the actual qualifying spin for purchase presentation. Awards are
  * zeroed so the landing/cascades can play without paying the entry spin. */
 purchaseTrigger(round:SpinResult):SpinResult{
  const trigger=JSON.parse(JSON.stringify(round)) as SpinResult;trigger.payout=0;trigger.wins=[];
  for(const frame of trigger.tumbleFeature!.frames){frame.wins=[];}
  return trigger;
 }
 demoSpin(bet:number){return this.find(bet,false);}
 bonusDemoSpin(bet:number){return this.find(bet,true);}
 private find(bet:number,bonus:boolean){const rng=tumbleRng(51602026);for(let n=0;n<20000;n++){const r=this.spin(bet,rng);if(bonus?!!r.rounds:!r.rounds&&r.payout>0)return r;}throw Error('Tumble outcome unavailable');}
 prepareBonusPurchase(bet:number,rng:()=>number):SpinResult{
  if(!this.hasBonus)throw Error('No bonus');
  for(let n=0;n<50000;n++){const result=this.spin(bet,rng);if(!result.rounds||result.rounds.length<2)continue;
   const extract=(r:SpinResult)=>{
    const source=r.rounds!,amounts=preSettlementAwards.get(source);if(!amounts)throw Error('Missing sampled tumble awards');
    const rounds=source.slice(1),trigger=this.purchaseTrigger(source[0]);
    rounds.forEach((round,i)=>{if(round.wins.length!==amounts[i+1].length)throw Error('Changed tumble awards after settlement');round.wins.forEach((win,j)=>win.amount=amounts[i+1][j]);});
    return {...this.finish(rounds,{freeSpinsAwarded:r.freeSpinsAwarded,featureOnly:r.featureOnly,featureName:r.featureName,bonusTriggerRound:trigger}),rounds};
   };
   if(result.featureChoices){const choice=result.featureChoices,results=choice.results.map(extract);return{...results[choice.defaultIndex],featureChoices:{...choice,results}};}return extract(result);
  }throw Error('Natural tumble bonus unavailable');
 }
}
