import {assetManager,AudioClip,resources,sys} from 'cc';
import {gameAudio} from './GameAudio';
import {featureAudioCatalog} from './FeatureAudioCatalog';

/** Web music uses MP3; Android retains its original OGG resources/backend. */
export function webAudioResource(path:string){
 const music=path.startsWith('slot-audio-v2/music-');
 return {path:music?path.replace('slot-audio-v2/','slot-audio-web-v1/'):path,extension:music?'.mp3':'.wav'};
}

const pending=new Map<string,Promise<void>>();
function preload(key:string,path:string,register:(url:string)=>Promise<void>):Promise<void>{
 const previous=pending.get(key);if(previous)return previous;
 const task=Promise.resolve().then(async()=>{
  const asset=webAudioResource(path),info=resources.getInfoWithPath(asset.path,AudioClip);
  if(!info)throw Error('Missing audio resource '+asset.path);
  // Resolve the bundled URL without resources.load(AudioClip): that decodes a
  // second copy through Cocos, whose failure path can leave loading unresolved.
  const url=assetManager.utils.getUrlWithUuid(info.uuid,{isNative:true,nativeExt:asset.extension});
  await register(url);
 }).catch(error=>console.warn('[Optional slot audio]',path,String(error))).finally(()=>{pending.delete(key);});
 pending.set(key,task);return task;
}

/** Caller must not wait for optional audio before admitting the player. */
export async function preloadSlotAudio(slot:string):Promise<void>{
 if(sys.isNative)return; // NativeGameAudio owns native loading and playback.
 await Promise.all([
  ...gameAudio.resourcesForSlot(slot).map(path=>preload('palette:'+path,path,url=>gameAudio.registerPaletteClip(path,url))),
  ...Object.entries(featureAudioCatalog[slot]||{}).map(([event,path])=>preload('feature:'+slot+'/'+event,path,url=>gameAudio.registerFeatureClip(slot,event,url))),
 ]);
}
