/** Frozen phase inputs, fitted before independent validation. */
export const KEEP_MODEL={"gate":0.07914554581711555,"freeGate":0.02,"baseWild":5.867409238127317,"freeWild":17.9423255134774};
export const KEEP_BASE_POTS=[[2,50],[3,25],[5,15],[10,8],[20,2]] as const;
export const KEEP_FREE_POTS=[[5,45],[10,30],[20,18],[50,6],[100,1]] as const;
export function keepUniform(rng:()=>number){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid Keep uniform');return u;}
export function keepPot(u:number,free:boolean){let x=u*100;const table=free?KEEP_FREE_POTS:KEEP_BASE_POTS;for(let tier=0;tier<table.length;tier++){x-=table[tier][1];if(x<0)return{tier,multiple:table[tier][0]};}throw Error('Invalid Keep pot');}
