export function parisUniform(rng:()=>number){const value=rng();if(!Number.isFinite(value)||value<0||value>=1)throw Error('Invalid Paris random value');return value;}
export function parisOrdinary(bet:number,rng:()=>number,input:ParisInput){const high=input.highByBet[bet]??1;let bets=pools.get(input);if(!bets){bets=new Map();pools.set(input,bets);}let pool=bets.get(bet);if(!pool||pool.high!==high){const w=weights.map((v,i)=>v*(i===0?high:1));pool={high,weights:w,sum:w.reduce((a,b)=>a+b,0)};bets.set(bet,pool);}let roll=parisUniform(rng)*pool.sum;for(let i=0;i<9;i++){roll-=pool.weights[i];if(roll<0)return i===8?'wild':i;}return 7;}
