import {Win} from '../slots/SlotMain';
/** Groups actual settled lines only; never re-evaluates or scales an award. */
export function wolfLineGroups(wins:Win[],board:string[],wild:string){
 const groups:{symbol:string;length:number;wins:Win[];amount:number;wildCells:number[]}[]=[];
 for(const win of wins){
  const length=new Set(win.cells.map(cell=>cell%5)).size;
  let group=groups.find(group=>group.symbol===win.symbol&&group.length===length);
  if(!group){group={symbol:win.symbol,length,wins:[],amount:0,wildCells:[]};groups.push(group);}
  group.wins.push(win);group.amount+=win.amount;
  group.wildCells=Array.from(new Set([...group.wildCells,...win.cells.filter(cell=>board[cell]===wild)]));
 }
 return groups;
}
