import type {ExpansionFrame,JoeyPuzzleStep} from '../slots/ExpansionCore';
/** Visible playback state only; never read the engine's already advanced progress. */
export const joeyPieceCount=(mask:number)=>Array.from({length:9},(_,piece)=>(mask>>piece)&1).reduce((n,value)=>n+value,0);
export function joeyIdleStep(progress:readonly number[]=[0,0]):JoeyPuzzleStep{
 return {phase:'collect',puzzle:(progress[1]||0)+1,mask:(progress[0]||0)&511};
}
export function joeyFlow(frame:ExpansionFrame){
 const s=frame.joeyPuzzle!;
 const params={puzzle:s.puzzle,count:joeyPieceCount(s.mask),missing:9-joeyPieceCount(s.mask),piece:(s.piece??0)+1,spin:s.spin||1,board:(s.board??0)+1,paid:frame.wins.reduce((n,w)=>n+w.amount,0)};
 const key=s.phase==='collect'?frame.action==='win'?'baseWin':'collect':s.phase==='piece'?s.fresh?'newPiece':'duplicate':s.phase==='confirmed'?s.fresh?'added':'kept':s.phase==='pay'&&params.paid===0?'noWin':s.phase;
 return {key:'ui.joey.'+key,params};
}
/** Commit the visible mask only after the piece arrives; source frames stay immutable. */
export function joeyPieceArrived(frame:ExpansionFrame):ExpansionFrame{
 const step=frame.joeyPuzzle;
 if(!step||step.phase!=='piece'||step.piece===undefined)return frame;
 const mask=step.mask|(1<<step.piece);
 return {...frame,joeyPuzzle:{...step,mask,phase:'confirmed'},panel:frame.panel?{...frame.panel,values:Array.from({length:9},(_,i)=>(mask>>i)&1)}:undefined};
}
/** These values come from the already capped frame awards, including zero-win boards. */
export function joeyBoardAward(frame:ExpansionFrame){
 const s=frame.joeyPuzzle;if(s?.phase!=='pay'||s.board===undefined)return null;
 if(frame.wins.some(w=>w.cells.some(cell=>Math.floor(cell/15)!==s.board)))throw Error('Joey line crosses an independent board');
 return {board:s.board,amount:frame.wins.reduce((n,w)=>n+w.amount,0)};
}
export function joeyRailLayout(contentWidth:number,top:number){
 const x=24,width=contentWidth-48,pieceSize=26,gap=4,gridWidth=pieceSize*3+gap*2;
 return {x,width,top,textWidth:width-gridWidth-20,gridX:x+width-gridWidth,gridY:top+30,pieceSize,gap,height:116};
}
