/** Source: MerkurXtip Pragmatic game rules pp49–50; see docs/slots/rhino-grand-ways.md.
 * This models bonus lifecycle only, not reel generation or payout timing. */
export interface RhinoChoice { spins:number; multiplier:number; }
export interface RhinoBonusState { remaining:number; multiplier:number; phase:'ready'|'spinning'|'complete'; }
function integer(value:number,min:number,max:number,label:string){if(!Number.isSafeInteger(value)||value<min||value>max)throw Error(`Invalid Rhino ${label}`);}
export function rhinoChoices(scatters:number):RhinoChoice[]{
 integer(scatters,4,6,'entry scatters');
 const extra=(scatters-4)*4;
 return [{spins:15+extra,multiplier:1},{spins:10+extra,multiplier:5},{spins:5+extra,multiplier:10}];
}
export function rhinoStartBonus(scatters:number,choice:number):RhinoBonusState{
 integer(choice,0,2,'resolved choice');
 const selected=rhinoChoices(scatters)[choice];
 return {remaining:selected.spins,multiplier:selected.multiplier,phase:'ready'};
}
function validate(state:RhinoBonusState){
 integer(state.remaining,0,Number.MAX_SAFE_INTEGER,'remaining');integer(state.multiplier,1,Number.MAX_SAFE_INTEGER,'multiplier');
 if(!['ready','spinning','complete'].includes(state.phase))throw Error('Invalid Rhino phase');
 if(state.phase==='complete'&&state.remaining!==0)throw Error('Completed Rhino bonus has spins');
 if(state.phase==='ready'&&state.remaining===0)throw Error('Ready Rhino bonus has no spins');
}
export function rhinoBeginSpin(state:RhinoBonusState):RhinoBonusState{
 validate(state);if(state.phase!=='ready')throw Error('Rhino spin is not ready');
 return {...state,remaining:state.remaining-1,phase:'spinning'};
}
/** Called once after all tumbles/scatters have resolved. UI presents this delta
 * at retrigger confirmation, never when the future result is generated. */
export function rhinoFinishSpin(state:RhinoBonusState,winningTumbles:number,scatters:number){
 validate(state);if(state.phase!=='spinning')throw Error('Rhino spin is not running');
 integer(winningTumbles,0,Number.MAX_SAFE_INTEGER,'winning tumbles');integer(scatters,0,6,'scatters');
 const addedSpins=scatters>=3?5:0,remaining=state.remaining+addedSpins,multiplier=state.multiplier+winningTumbles;
 integer(remaining,0,Number.MAX_SAFE_INTEGER,'remaining');integer(multiplier,1,Number.MAX_SAFE_INTEGER,'multiplier');
 const after:RhinoBonusState={remaining,multiplier,phase:remaining?'ready':'complete'};
 return {before:{...state},addedSpins,after};
}

/** The provider Mystery distribution is private. Our declared fixed law picks
 * uniformly from the three confirmed legal packages, before any free outcomes
 * are generated. It never chooses a package by its winning result. */
export function rhinoMysteryChoice(rng:()=>number):0|1|2{
 const value=rng();if(!Number.isFinite(value)||value<0||value>=1)throw Error('Invalid Rhino Mystery input');
 return Math.floor(value*3) as 0|1|2;
}
