import{VaultWorkshopSlot,VAULT_ID}from'./VaultWorkshopSlot';
import{expansionRng}from'./ExpansionCore';
import{VAULT_INPUTS}from'./VaultWorkshopMath';
export const VAULT_WITNESSES={"no-win":{"seed":24355961,"payout":0},"two-stamp":{"seed":27288290,"payout":1950,"value":3.9,"multipliers":[3,2]},"one-stamp":{"seed":28265733,"payout":195,"value":0.975,"multipliers":[2,0]},"no-stamp":{"seed":33152948,"payout":98,"value":0.975,"multipliers":[0,0]},"regular":{"seed":106461173,"payout":100},"purchase":{"seed":24455961,"payout":8580}} as const;
export function vaultWorkshopAudit(params:URLSearchParams){const slot=new VaultWorkshopSlot(),outcome=params.get('audit-outcome')||'two-stamp',w=(VAULT_WITNESSES as Record<string,{seed:number;payout:number}>)[outcome],raw=slot.prepareBonusPurchase.bind(slot);
 slot.demoSpin=bet=>{const witness=w&&outcome!=='purchase'?w:VAULT_WITNESSES['two-stamp'],r=slot.spin(bet,expansionRng(witness.seed));if(bet===100&&r.payout!==witness.payout)throw Error('Stale Vault witness');return r;};
 slot.prepareBonusPurchase=bet=>outcome==='lowest'?raw(bet,()=>0):raw(bet,expansionRng(VAULT_WITNESSES.purchase.seed));
 if(outcome==='highest')slot.demoSpin=bet=>{const input=VAULT_INPUTS.find(v=>v.bet===bet)!;let calls=0;const u=[1-input.vault/2,1-input.stamp/2,1-input.stamp/2,.999,.999,.999];return slot.spin(bet,()=>u[calls++]);};return slot;
}
