import {Color,Graphics,Node,UIOpacity,Vec3,tween} from 'cc';
import {SLOT_BUTTON_ART_INSET} from './ResponsiveLayout';

// Native cabinet artwork: enamel, faceted gems and bevels stay crisp at
// every phone size, without scaling the game's low-resolution symbol textures.
type Point=readonly [number,number];
function polygon(g:Graphics,points:readonly Point[],color:string){
 g.fillColor=new Color(color);g.moveTo(points[0][0],points[0][1]);
 for(let i=1;i<points.length;i++)g.lineTo(points[i][0],points[i][1]);
 g.close();g.fill();
}
function rect(g:Graphics,x:number,y:number,w:number,h:number,color:string){g.fillColor=new Color(color);g.rect(x,y,w,h);g.fill();}
function mixedColor(top:Color,bottom:Color,t:number){return new Color(Math.round(top.r+(bottom.r-top.r)*t),Math.round(top.g+(bottom.g-top.g)*t),Math.round(top.b+(bottom.b-top.b)*t));}
function enamelGradient(g:Graphics,w:number,h:number,top:string,bottom:string,inset=12){
 const a=new Color(top),b=new Color(bottom),rows=64,span=h-inset*2,step=span/rows;
 for(let row=0;row<rows;row++){
  const depth=row*step,edge=Math.max(0,12-Math.min(depth,span-depth-step)),x=inset+edge;
  g.fillColor=mixedColor(a,b,row/(rows-1));g.rect(x,-inset-depth-step,w-x*2,step+.4);g.fill();
 }
}
function roundedEnamelGradient(g:Graphics,w:number,h:number,top:string,bottom:string,inset:number,radius:number){
 const a=new Color(top),b=new Color(bottom),span=h-inset*2,rows=96,step=span/rows;
 for(let row=0;row<rows;row++){
  const depth=(row+.5)*step,near=Math.min(depth,span-depth),edge=near<radius?radius-Math.sqrt(Math.max(0,radius*radius-(radius-near)*(radius-near))):0;
  g.fillColor=mixedColor(a,b,row/(rows-1));g.rect(inset+edge,-inset-(row+1)*step,w-(inset+edge)*2,step+.15);g.fill();
 }
}
function plate(g:Graphics,w:number,h:number,inset:number,color:string,corner=18){
 const l=inset,r=w-inset,t=-inset,b=-h+inset,c=Math.max(3,corner-inset*.5);
 polygon(g,[[l+c,t],[r-c,t],[r,t-c],[r,b+c],[r-c,b],[l+c,b],[l,b+c],[l,t-c]],color);
}
export function casinoSpark(g:Graphics,x:number,y:number,r=7,color='#fff5bc'){
 polygon(g,[[x,y+r],[x+r*.28,y+r*.28],[x+r,y],[x+r*.28,y-r*.28],[x,y-r],[x-r*.28,y-r*.28],[x-r,y],[x-r*.28,y+r*.28]],color);
}
export function casinoGem(g:Graphics,x:number,y:number,size:number,pink=false){
 const r=size/2;
 polygon(g,[[x,y+r+3],[x+r+3,y],[x,y-r-3],[x-r-3,y]],'#754019');
 polygon(g,[[x,y+r+1],[x+r+1,y],[x,y-r-1],[x-r-1,y]],'#ffe49a');
 polygon(g,[[x,y+r-2],[x+r-2,y],[x,y-r+2],[x-r+2,y]],pink?'#d936a6':'#15cbbf');
 polygon(g,[[x,y+r-2],[x+r-2,y],[x,y],[x-r+2,y]],pink?'#ff89dc':'#9cfff0');
 polygon(g,[[x,y],[x+r-2,y],[x,y-r+2]],pink?'#9e206c':'#087889');
 rect(g,x-2,y+2,4,4,'#fff9df');
}
/** Coordinates use a top-left origin, matching the shared GameUI plates. */
export function casinoPlate(g:Graphics,w:number,h:number,kind:'console'|'win'|'celebration'){
 g.clear();
 if(kind==='win'||kind==='celebration'){
  // Rounded gold trim surrounds the whole panel; amount/caption remain unframed.
  const rim=kind==='win'?8:10,radius=kind==='win'?24:32;
  for(const [inset,color]of [[0,'#915532'],[2,'#f4cf80'],[5,'#ffe4a3'],[rim,kind==='win'?'#264963':'#613691']]as const){
   g.fillColor=new Color(color);g.roundRect(inset,-h+inset,w-inset*2,h-inset*2,radius-inset);g.fill();
  }
  roundedEnamelGradient(g,w,h,kind==='win'?'#305e7a':'#7147a0',kind==='win'?'#264963':'#5d3687',rim,radius-rim);
 }else{
  for(const [inset,color]of [[0,'#301449'],[3,'#a85d2e'],[6,'#ffda75'],[10,'#613691']]as const)plate(g,w,h,inset,color);
  enamelGradient(g,w,h,'#7147a0','#5d3687');
 }
 // Actual gem/star motifs. No corner brackets or stripe ornaments.
 casinoOrnaments(g.node,w,h,kind);
}
function casinoOrnaments(parent:Node,w:number,h:number,kind:'console'|'win'|'celebration'){
 const add=(name:string,x:number,y:number,paint:(g:Graphics)=>void,index:number)=>{
  const node=new Node(name);node.layer=parent.layer;parent.addChild(node);node.setPosition(x,y);paint(node.addComponent(Graphics));
  const opacity=node.addComponent(UIOpacity);opacity.opacity=225;
  tween(opacity).delay(index*.25).to(1.3,{opacity:180},{easing:'sineInOut'}).to(1.5,{opacity:240},{easing:'sineInOut'}).union().repeatForever().start();
  tween(node).delay(index*.2).by(1.7,{position:new Vec3(0,2,0)},{easing:'sineInOut'}).by(1.7,{position:new Vec3(0,-2,0)},{easing:'sineInOut'}).union().repeatForever().start();
 };
 for(const side of [0,1]){
  const x=side?w-49:49,d=side?-1:1;
  if(kind==='win'){
   add('Floating WIN gem',x,-h*.45,g=>casinoGem(g,0,0,30),side);
   add('Quiet WIN sparkle',x+d*37,-h*.38,g=>casinoSpark(g,0,0,9),side+2);
   add('Small WIN sparkle',x+d*54,-h*.62,g=>casinoSpark(g,0,0,5),side+4);
  }else{
   add('Floating cabinet jewel',x,-h+30,g=>casinoGem(g,0,0,16,true),side);
   add('Quiet cabinet sparkle',x+d*30,-h+30,g=>casinoSpark(g,0,0,5),side+2);
  }
 }
}
export function casinoInlay(g:Graphics,w:number,h:number,teal:boolean){
 for(const [inset,color]of [[0,'#331c54'],[3,teal?'#70d8c2':'#c89cdd'],[6,teal?'#20516b':'#44276c']]as const)plate(g,w,h,inset,color,11);
}
function disc(g:Graphics,x:number,y:number,r:number,color:string){
 g.fillColor=new Color(color);g.circle(x,y,r);g.fill();
}
/** Concentric brass rims and a raised enamel plunger recall arcade controls. */
export function casinoButton(g:Graphics,size:number,kind:'play'|'stop'|'auto'|'help'|'bet',disabled:boolean){
 g.clear();const x=size/2,y=-size/2,r=size/2-SLOT_BUTTON_ART_INSET,u=Math.min(1,size/112);
 const colors=disabled?['#444960','#687188','#8894a1']:kind==='play'?['#075c57','#15927b','#61ce9c']:kind==='stop'?['#85263f','#bf405b','#f27686']:kind==='auto'?['#572276','#8942ad','#d48bd5']:kind==='help'?['#21476c','#3978a0','#82b4ca']:['#176368','#32939a','#82c9bd'];
 disc(g,x,y,r,'#2b173d');disc(g,x,y,r-2*u,disabled?'#717787':'#8a4c2b');
 disc(g,x,y+u,r-4*u,disabled?'#a3a7ad':'#ffe39b');disc(g,x,y-u,r-7*u,disabled?'#646978':'#b67c39');
 disc(g,x,y+2*u,r-9*u,disabled?'#c0c4c6':'#fff0b7');disc(g,x,y-2*u,r-11*u,colors[0]);
 // Shifted nested discs form a rounded bevel, without any decorative stripes.
 disc(g,x,y+2*u,r-14*u,colors[2]);disc(g,x,y-u,r-15*u,colors[1]);
 const faceR=r-17*u,top=new Color(colors[2]),bottom=new Color(colors[1]),rows=32,step=faceR*2/rows;
 for(let row=0;row<rows;row++){
  const dy=faceR-row*step-step/2,half=Math.sqrt(Math.max(0,faceR*faceR-dy*dy));
  g.fillColor=mixedColor(top,bottom,row/(rows-1));g.rect(x-half,y+dy-step/2,half*2,step+.3);g.fill();
 }
}
function pixelGlyph(g:Graphics,rows:readonly string[],size:number,color:string,shadow:string){
 const unit=size/Math.max(rows.length,rows[0].length),left=-rows[0].length*unit/2,top=rows.length*unit/2;
 for(const [dy,ink]of [[-unit*.45,shadow],[0,color]]as const)for(let y=0;y<rows.length;y++)for(let x=0;x<rows[y].length;x++)if(rows[y][x]==='1')rect(g,left+x*unit,top-(y+1)*unit+dy,unit+.15,unit+.15,ink);
}
export function casinoControlIcon(g:Graphics,glyph:'plus'|'minus'|'help'|'spin'|'stop'|'play',size:number,disabled:boolean,active=false){
 if(glyph==='play'){casinoPlayIcon(g,size,false,disabled);return;}
 if(glyph==='stop'){casinoStopIcon(g,size,disabled,true);return;}
 const color=disabled?'#c2c6cf':active?'#8efbe4':'#fff1bb',shadow=disabled?'#4a4e60':'#3a244e';
 const rows=glyph==='plus'?['001100','001100','111111','111111','001100','001100']:glyph==='minus'?['000000','000000','111111','111111','000000','000000']:glyph==='help'?['01110','11011','00011','00110','00100','00000','00100']:['000001000','001111100','011001110','110000100','110000000','000000011','001000011','011100110','001111100','000100000'];
 pixelGlyph(g,rows,size,color,shadow);
}
/** Raised stop squares: red for manual spin, amber for AUTO. */
function casinoStopIcon(g:Graphics,size:number,disabled:boolean,automatic=false){
 const side=size*.74,half=side/2,bevel=side*.14,inner=half-bevel,depth=side*.09;
 const colors=automatic
  ?disabled?['#493d27','#8e784a','#b8a16b','#6d5534','#9b814b']:['#533014','#efa52b','#ffe18a','#a45a13','#cc7b19']
  :disabled?['#49313d','#86545c','#b47b80','#70414e','#98545d']:['#491827','#ed3b43','#ff8375','#9b1830','#c72138'];
 rect(g,-half,-half-depth,side,side,colors[0]);
 rect(g,-half,-half,side,side,colors[1]);
 polygon(g,[[-half,half],[half,half],[inner,inner],[-inner,inner]],colors[2]);
 polygon(g,[[-half,half],[-inner,inner],[-inner,-inner],[-half,-half]],colors[2]);
 polygon(g,[[-half,-half],[-inner,-inner],[inner,-inner],[half,-half]],colors[3]);
 polygon(g,[[half,half],[half,-half],[inner,-inner],[inner,inner]],colors[4]);
}
export function casinoPlayIcon(g:Graphics,size:number,stop:boolean,disabled:boolean){
 const face=disabled?'#c2c6cf':'#fff1bb',shade=disabled?'#4a4e60':'#075c57';
 if(stop){
  casinoStopIcon(g,size,disabled);
 }else{
  // A compact, clean arcade play emblem, centred optically in the round plunger.
  const points:Point[]=[[-size*.30,size*.40],[size*.40,0],[-size*.30,-size*.40]];
  polygon(g,points.map(([x,y])=>[x,y-2]as Point),shade);polygon(g,points,face);
 }
}
export function casinoBonusButton(g:Graphics,w:number,h:number,disabled:boolean){
 g.clear();
 for(const [inset,color]of [[0,'#2b173d'],[3,disabled?'#7b7f89':'#9e5d30'],[6,disabled?'#a1a6af':'#ffe39b'],[10,disabled?'#606579':'#a36a38'],[13,disabled?'#43495e':'#482468'],[16,disabled?'#646c80':'#9052b4']]as const){
  g.fillColor=new Color(color);g.roundRect(inset,-h+inset,w-inset*2,h-inset*2,(h-inset*2)/2);g.fill();
 }
}
/** A jewel-set crown for large wins, with a silhouette legible at phone scale. */
export function casinoCrown(g:Graphics,size:number){
 const u=size/100;
 const crown:Point[]=[[-43,-14],[-50,27],[-23,10],[0,43],[23,10],[50,27],[43,-14]];
 polygon(g,crown.map(([x,y])=>[x*u,y*u]as Point),'#9c5527');
 polygon(g,crown.map(([x,y])=>[x*u,(y+4)*u]as Point),'#ffe381');
 polygon(g,[[-34*u,-8*u],[-39*u,18*u],[-20*u,3*u],[0,29*u],[20*u,3*u],[39*u,18*u],[34*u,-8*u]],'#e8a72e');
 rect(g,-40*u,-23*u,80*u,13*u,'#a96a28');rect(g,-40*u,-18*u,80*u,7*u,'#fff0a6');
 casinoGem(g,0,3*u,20*u,true);casinoGem(g,-27*u,0,11*u);casinoGem(g,27*u,0,11*u);
 for(const x of [-50,0,50])casinoSpark(g,x*u,(x===0?48:32)*u,5*u);
}
export function retroTransitionBackdrop(g:Graphics,w:number,h:number){
 rect(g,0,-h,w,h,'#17152f');
 for(let i=0;i<44;i++){
  const x=24+(i*137)%(w-48),y=32+(i*173)%(h*.68),size=i%4===0?6:3;
  rect(g,x,-y,size,size,i%3===0?'#e1a4c6':i%3===1?'#847cb7':'#6bd2ca');
  if(i%7===0){rect(g,x-4,-y+2,12,2,'#e1a4c6');rect(g,x+1,-y-3,2,12,'#e1a4c6');}
 }
 // Chunky skyline silhouettes and a tiled arcade floor, with no scanline overlay.
 const horizon=h*.78;
 for(const side of [0,1])for(let i=0;i<4;i++){
  const width=32+(i%2)*16,height=64+(i*37)%120,x=side?w-(i+1)*48:i*48;
  rect(g,x,-horizon,width,height,'#31244c');rect(g,x+10,-horizon+height-18,8,8,i%2?'#bf648f':'#68a2a8');
 }
 for(let row=0,y=horizon;y<h;row++){
  const tileH=20+row*7,tileW=48+row*12;
  for(let col=-1;col<w/tileW+1;col++)rect(g,col*tileW+(row%2?tileW/2:0),-y-tileH,tileW,tileH,(row+col)%2?'#352552':'#261e41');
  y+=tileH;
 }
}
export function retroLoadingMeter(g:Graphics,w:number,progress:number){
 g.clear();const count=16,gap=5,cell=(w-gap*(count-1))/count,filled=Math.ceil(Math.max(0,Math.min(1,progress))*count);
 for(let i=0;i<count;i++)rect(g,i*(cell+gap),-16,cell,16,i<filled?'#7ee4b0':'#302447');
}
