/** Transcribed at total stake CZK20, MerkurXtip rules p50.
 * Pure evaluator only: weights, tumbles, art and UI are not connected yet. */
export const RHINO_SYMBOLS=['cheetah','gorilla','crocodile','hyena','flamingo','a','k','q','j','ten'] as const;
/** Indexed by consecutive reel count 0..6; multiples of total stake. */
export const RHINO_PAYS:readonly (readonly number[])[]=[
 [0,0,1,2,10,25,50], [0,0,0,1,2,2.5,5], [0,0,0,.3,.5,1,2.5],
 [0,0,0,.3,.5,.8,2], [0,0,0,.2,.4,.6,1.5],
 [0,0,0,.2,.4,.6,1.5], [0,0,0,.2,.4,.6,1.5],
 [0,0,0,.1,.2,.4,1], [0,0,0,.1,.2,.4,1], [0,0,0,.1,.2,.4,1],
];
export const RHINO_WILD=10,RHINO_SCATTER=11;
export interface RhinoBoard { columns:number[][]; top:number[]; }
export interface RhinoWin { symbol:number; reels:number; ways:number; cells:number[]; amount:number; }
/** Main cell id = col*7+row, top cell id=42+index. Logical IDs are stable
 * through changes in reel height; this is not the old fixed-row UI layout. */
/** Board validation is also used by gravity; it does not evaluate awards. */
export function validateRhinoBoard(board:RhinoBoard){
 if(board.columns.length!==6||board.top.length!==4)throw Error('Invalid Rhino reel layout');
 for(const symbols of board.columns){
  if(symbols.length<2||symbols.length>7)throw Error('Invalid Rhino reel height');
  for(const symbol of symbols)if(!Number.isInteger(symbol)||symbol<0||symbol>RHINO_SCATTER||symbol===RHINO_WILD)throw Error('Invalid Rhino main symbol');
 }
 for(const symbol of board.top)if(!Number.isInteger(symbol)||symbol<0||symbol>RHINO_SCATTER)throw Error('Invalid Rhino top symbol');
}
export function rhinoEvaluate(board:RhinoBoard,bet:number){
 if(!Number.isFinite(bet)||bet<=0)throw Error('Invalid Rhino bet');
 validateRhinoBoard(board);
 const matches=board.columns.map(()=>Array.from({length:10},()=>[] as number[])),scatterCells:number[]=[],removed=new Set<number>();
 for(let col=0;col<6;col++){
  const column=board.columns[col];
  for(let row=0;row<column.length;row++){const symbol=column[row],cell=col*7+row;if(symbol===RHINO_SCATTER)scatterCells.push(cell);else matches[col][symbol].push(cell);}
  if(col>0&&col<5){const symbol=board.top[col-1],cell=41+col;if(symbol===RHINO_SCATTER)scatterCells.push(cell);else if(symbol===RHINO_WILD)for(let n=0;n<10;n++)matches[col][n].push(cell);else matches[col][symbol].push(cell);}
 }
 const wins:RhinoWin[]=[];
 for(let symbol=0;symbol<RHINO_SYMBOLS.length;symbol++){
  let reels=0,ways=1;const cells:number[]=[];
  for(const col of matches){const found=col[symbol];if(!found.length)break;reels++;ways*=found.length;cells.push(...found);}
  const pay=RHINO_PAYS[symbol][reels];if(pay){wins.push({symbol,reels,ways,cells,amount:bet*pay*ways});for(const cell of cells)removed.add(cell);}
 }
 const payout=wins.reduce((sum,w)=>sum+w.amount,0);
 if(!Number.isFinite(payout))throw Error('Rhino payout overflow');
 return {wins,payout,ways:board.columns.reduce((n,col,index)=>n*(col.length+(index>0&&index<5?1:0)),1),scatterCells,removedCells:Array.from(removed)};
}
