import {slots} from '../slots/SlotRegistry';
import {SlotMain} from '../slots/SlotMain';
import {buyBonusResult,canBuyBonus,BONUS_COST_MULTIPLIER} from '../slots/BonusBuy';

/** Preserve class methods while isolating every mutable field from live games. */
function copy<T>(value:T,seen=new Map<object,any>()):T{
 if(value===null||typeof value!=='object')return value;
 if(seen.has(value))return seen.get(value);
 const out:any=value instanceof Map?new Map():value instanceof Set?new Set():Array.isArray(value)?[]:Object.create(Object.getPrototypeOf(value));seen.set(value,out);
 if(value instanceof Map)value.forEach((v,k)=>out.set(copy(k,seen),copy(v,seen)));
 else if(value instanceof Set)value.forEach(v=>out.add(copy(v,seen)));
 else for(const key of Object.keys(value))out[key]=copy((value as any)[key],seen);
 return out;
}
// Captured at module startup, before user gameplay can accumulate progress.
const initial=new Map(slots.map(slot=>[slot.config.id,copy(slot)]));
export type SimulationMode='normal'|'purchase';
export interface MathStats {requested:number;completed:number;hits:number;profits:number;moneyIn:number;moneyOut:number;maxPayout:number;cancelled:boolean;}
export function simulationCount(text:string){if(!/^\d+$/.test(text.trim()))throw Error('횟수는 1~1,000,000 정수로 입력하세요.');const n=Number(text);if(!Number.isSafeInteger(n)||n<1||n>1000000)throw Error('횟수는 1~1,000,000 정수로 입력하세요.');return n;}
export function simulationSlot(id:string){const source=initial.get(id);if(!source)throw Error('등록되지 않은 슬롯입니다.');return copy(source);}
export async function runMathSimulation(id:string,mode:SimulationMode,count:number,bet:number,options:{cancelled?:()=>boolean;onProgress?:(stats:MathStats)=>void;rng?:()=>number;yield?:()=>Promise<void>}={}):Promise<MathStats>{
 simulationCount(String(count));const slot=simulationSlot(id);
 if(!slot.bets.includes(bet))throw Error('이 슬롯에서 지원하는 베팅을 입력하세요: '+slot.bets.join(', '));
 if(mode!=='normal'&&mode!=='purchase')throw Error('잘못된 모드입니다.');
 if(mode==='purchase'&&!canBuyBonus(slot))throw Error('이 슬롯은 바이보너스를 지원하지 않습니다.');
 const cost=bet*(mode==='purchase'?BONUS_COST_MULTIPLIER:1);
 if(!Number.isSafeInteger(cost*count)||!Number.isSafeInteger(bet*slot.maxWin*count))throw Error('계산 범위를 초과합니다. 횟수나 베팅을 줄이세요.');
 const stats:MathStats={requested:count,completed:0,hits:0,profits:0,moneyIn:0,moneyOut:0,maxPayout:0,cancelled:false};
 const progress:Record<string,number[]>={},game=slot as SlotMain&{setProgress?:(p:Record<string,number[]>)=>void};
 const rng=options.rng||Math.random,pause=options.yield||(()=>new Promise<void>(r=>setTimeout(r,0)));
 let deadline=Date.now()+12;
 for(let i=0;i<count;i++){
  if(options.cancelled?.()){stats.cancelled=true;break;}
  game.setProgress?.(progress);
  const result=mode==='normal'?slot.spin(bet,rng):buyBonusResult(slot,bet,rng);
  // Use the engine's declared default choice, including its cumulative settlement.
  const settled=result.featureChoices?.results[result.featureChoices.defaultIndex]||result.moonChoices?.[result.moonDefaultChoice||0]||result;
  if(!Number.isSafeInteger(settled.payout)||settled.payout<0)throw Error('잘못된 정산 결과로 중단했습니다.');
  if(mode==='normal'&&settled.progressUpdate)progress[settled.progressUpdate.key]=[...settled.progressUpdate.values];
  stats.completed++;stats.hits+=Number(settled.payout>0);stats.profits+=Number(settled.payout>cost);stats.moneyIn+=cost;stats.moneyOut+=settled.payout;stats.maxPayout=Math.max(stats.maxPayout,settled.payout);
  if(Date.now()>=deadline){options.onProgress?.({...stats});await pause();deadline=Date.now()+12;}
 }
 options.onProgress?.({...stats});return stats;
}
