import {WhitePeakSlot} from './WhitePeakSlot';import {EXPANSION_SPECS} from './ExpansionCatalog';
/** Source before-call seeds from continuous complete paid-spin prefixes.
 * Offline QA only; no injected boards or production RNG selection. */
export const PEAK_AUDIT_SEEDS:Record<string,number>={empty:3268975297,free:2324553377,unpaidBear:4016959705,multi:2044346827,multiBear:2518936555};
export function whitePeakAudit(params:URLSearchParams){const slot=new WhitePeakSlot(EXPANSION_SPECS.find(s=>s.id==='white-peak-impact')!),outcome=params.get('audit-peak-case')||params.get('audit-outcome')||'',kind=({'no-win':'empty','multi-win':'multi'} as Record<string,string>)[outcome]||outcome,initial=PEAK_AUDIT_SEEDS[kind];if(initial!==undefined){const spin=(bet:number)=>{let seed=initial;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};const r=slot.spin(bet,rng);if(kind==='free'||kind==='multiBear'){if(r.rounds?.length!==11||r.freeSpinsAwarded!==10)throw Error('Stale peak free audit seed');}else if(r.rounds||kind==='empty'&&r.wins.length||kind==='unpaidBear'&&!r.board.includes(slot.id('wild')))throw Error('Stale peak base audit seed');return r;};slot.demoSpin=spin;if(kind==='free'||kind==='multiBear')slot.bonusDemoSpin=spin;}return slot;}
