import {ExpansionSlot,ExpansionFrame,Geometry,expansionCells as cells,randomIndex} from './ExpansionCore';
import {SpinResult,Win} from './SlotMain';
import {drawThreeGateBoard} from './ConditionalGateBoard';
import {SILVER_MODEL,silverOrdinaryInput,silverUniform} from './SilverMath';
/** Mighty Silver Deluxe's two Repeat Win branches; probabilities and award sizes are local. */
export class SilverMineSlot extends ExpansionSlot {
 constructor(spec:ConstructorParameters<typeof ExpansionSlot>[0]){
  super(spec);
  for(const name of ['free','hold','portrait'])this.config.symbols.push({id:this.id(name),name,color:'#e7c482',weight:0,payout:0});
  this.config.description='5×3 · 25라인 · 왼쪽부터 연결\n나무 표식 3개 이상: 같은 반복 상금을 사용하는 두 보너스 중 선택합니다.\n무료 10회: 나무 표식마다 반복 상금 지급. 무료 중 재발동은 없습니다.\n코인 고정: 리스핀 3회. 새 코인은 3회로 복구하며 마지막에 고정 코인을 한 번씩 지급합니다.\n반복 상금·출현 확률은 로컬 규칙이며 서버 공유 잭팟은 적용하지 않습니다.';
 }
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-silver';}
 unit(symbol:number,count:number){return (.025+.015*(8-symbol))*Math.pow(2,Math.max(0,count-3));}
 draw(bet:number,rng:()=>number,g:Geometry=this.geometry,value?:number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');const board=Array.from({length:15},()=>this.id(silverOrdinaryInput(bet,rng,value))),q=(value===undefined?SILVER_MODEL.base:SILVER_MODEL.freeByValue[value]).scatterPerReel;
  for(let col=0;col<5;col++)if(silverUniform(rng)>=1-q)board[randomIndex(rng,3)*5+col]=this.id('scatter');return board;
 }
 private value(rng:()=>number){return [2,4,6,8,12,20][randomIndex(rng,6)];}
 private award(cell:number,bet:number,value:number,symbol='coin'):Win{return{line:-1,symbol:this.id(symbol),cells:[cell],amount:Math.round(bet*value),multiplier:value};}
 private repeatFree(base:SpinResult,bet:number,rng:()=>number,value:number){
  const rounds=[base];for(let left=9;left>=0;left--){const b=this.draw(bet,rng,this.geometry,value),r=this.ordinary(b,bet,'은광 무료 회전 · 일반 라인'),trees=cells(b,this.id('scatter'));
   if(trees.length){const f=this.frame(b,'collect','나무 표식마다 반복 상금',trees);f.wins=trees.map(c=>this.award(c,bet,value,'scatter'));f.coinAwards=f.wins.map(win=>({cell:win.cells[0],win}));r.expansionFeature!.frames.push(f);}
   for(const f of r.expansionFeature!.frames)f.panel={label:'SILVER FREE',values:[left,10,value],columns:2};r.freeSpinsRemaining=left;rounds.push(r);
  }return this.finish(rounds,{freeSpinsAwarded:10,featureOnly:false});
 }
 private hold(base:SpinResult,board:string[],bet:number,rng:()=>number,value:number){
  const held=new Set(cells(board,this.id('scatter'))),rounds=[base],snapshots:ExpansionFrame[]=[],landing=SILVER_MODEL.holdLandingByInitial[held.size]??.075;let left=3;
  const frame=(action:ExpansionFrame['action'],caption:string,focus:number[]=[],previous=Array.from(held))=>{const b=Array.from({length:15},(_,c)=>held.has(c)?this.id('coin'):''),f=this.frame(b,action,caption,focus,{held:previous,remaining:left,panel:{label:'SILVER HOLD',values:[held.size,15,value],columns:2}});snapshots.push(f);return f;};
  rounds.push(this.round(bet,[frame('state','나무 코인 고정 · 리스핀 3회')]));
  while(left>0&&held.size<15){left--;const previous=Array.from(held),landed:number[]=[];for(let c=0;c<15;c++)if(!held.has(c)&&silverUniform(rng)<landing){held.add(c);landed.push(c);}const fs=[frame('reels','빈칸 리스핀 · 고정 코인 유지',[],previous)];if(landed.length){left=3;fs.push(frame('effect','새 반복 상금 코인 · 3회 복구',landed));}fs.push(frame('state','남은 리스핀 '+left+'회'));rounds.push(this.round(bet,fs));}
  left=0;const paid=frame('win','고정 반복 상금 · 한 번씩 지급',Array.from(held));paid.wins=Array.from(held).map(c=>this.award(c,bet,value));rounds.push(this.round(bet,[paid]));const awards=new Map(paid.wins.map(win=>[win.cells[0],win]));for(const f of snapshots)f.coinAwards=cells(f.board,this.id('coin')).map(cell=>({cell,win:awards.get(cell)!}));return this.finish(rounds,{featureOnly:true});
 }
 private branches(base:SpinResult,b:string[],bet:number,rng:()=>number,value:number){const frames=base.expansionFeature!.frames;frames[frames.length-1].panel={label:'SILVER REPEAT',values:[value],columns:1};return this.choices('은광 반복 상금 선택',['무료 10회','코인 고정 리스핀'],[this.repeatFree(JSON.parse(JSON.stringify(base)),bet,rng,value),this.hold(JSON.parse(JSON.stringify(base)),b,bet,rng,value)]);}
 play(board:string[],bet:number,rng:()=>number){this.validate(board,bet);const base=this.ordinary(board,bet),trees=cells(board,this.id('scatter'));if(trees.length<3)return this.finish([base]);const value=this.value(rng),f=this.frame(board,'trigger','나무 표식 · 반복 상금 선택',trees);f.wins=[this.award(trees[0],bet,value,'scatter')];base.expansionFeature!.frames.push(f);return this.branches(base,board,bet,rng,value);}
 prepareBonusPurchase(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid bet');const pool=this.config.symbols.filter(s=>s.weight>0),weighted=(r:()=>number,p:{id:string;weight:number}[])=>{let n=r()*p.reduce((v,s)=>v+s.weight,0);for(const s of p){n-=s.weight;if(n<0)return s.id;}return p[p.length-1].id;},board=drawThreeGateBoard(()=>pool,this.id('scatter'),rng,weighted),base=this.round(bet,[this.frame(board,'trigger','독립 은광 보너스 구매',cells(board,this.id('scatter')))]);return this.purchaseFromResult(this.branches(base,board,bet,rng,this.value(rng)));}
}
