export type DrumInputs = {
  gate: number; freeGate: number; wild: number;
  baseZeroByBet: Record<number, number>;
  freeZeroByRowsBet: Record<number, Record<number, number>>;
};
/** Per-reel source-supported inputs, with at most one SCAT and middle WILDs. */
export function drumInputBoard(id: string, model: DrumInputs, bet: number, rng: () => number, rows = 3, free = false, conditional = false) {
  if (![3, 4, 5, 6].includes(rows) || conditional && (free || rows !== 3 || model.gate <= 0)) throw Error('Invalid Drum input mode');
  const zero = free ? model.freeZeroByRowsBet[rows]?.[bet] : model.baseZeroByBet[bet];
  if (!Number.isFinite(zero) || zero < 0 || zero + model.wild > 1 ||
      ![model.gate, model.freeGate, model.wild].every(q => Number.isFinite(q) && q >= 0 && q <= 1)) throw Error('Invalid Drum frequencies');
  const uniform = () => { const v = rng(); if (!Number.isFinite(v) || v < 0 || v >= 1) throw Error('Invalid Drum uniform'); return v; };
  const board = Array<string>(rows * 5), rest = [6, 7, 8, 10, 12, 14, 16];
  for (let col = 0; col < 5; col++) {
    const sample = uniform(), gate = conditional && col < 3 || sample < (free ? model.freeGate : model.gate);
    const gateRow = Math.floor(uniform() * rows), wild = col > 0 && col < 4 ? model.wild : 0;
    const pool = [zero, ...rest.map(q => (1 - zero - wild) * q / 73), wild];
    for (let row = 0; row < rows; row++) {
      let roll = uniform(), symbol = wild > 0 ? 8 : 7;
      for (let n = 0; n < pool.length; n++) { roll -= pool[n]; if (roll < 0) { symbol = n; break; } }
      board[row * 5 + col] = id + '-' + (symbol === 8 ? 'wild' : symbol);
    }
    if (gate) board[gateRow * 5 + col] = id + '-scatter';
  }
  return board;
}
