import {ExpansionSlot,Geometry} from './ExpansionCore';
import {SpinResult} from './SlotMain';
import {GAZE_MODEL,gazeUniform,gazeOrdinary} from './GazeMath';
/** Medusa Magic center Cash Zone. Exact strips, awards and tier progression are local adaptations. */
export class SerpentGazeSlot extends ExpansionSlot {
 private drawingFree=false;
 unit(symbol:number,count:number){return(.025+.015*(8-symbol))*2**Math.max(0,count-3);}
 prize(board:string[],bet:number,multiple:number,cells:number[],caption:string,g:Geometry=this.geometry){const frame=super.prize(board,bet,multiple,cells,caption,g);for(const win of frame.wins){win.amount=Math.round(bet*multiple);win.multiplier=multiple;}return frame;}
 constructor(spec:ConstructorParameters<typeof ExpansionSlot>[0]){super(spec);
  for(const name of ['coin','eye','portrait','gaze'])this.config.symbols.push({id:this.id(name),name,color:'#54dc9d',weight:0,payout:0});
  const seen=new Set(this.paylines.map(p=>p.join(',')));for(let n=0;this.paylines.length<50&&n<243;n++){let v=n;const rows=Array.from({length:5},()=>{const r=v%3;v=Math.floor(v/3);return r;}),line=rows.map((r,c)=>r*5+c),key=line.join(',');if(!seen.has(key)&&rows.every((r,c)=>!c||Math.abs(r-rows[c-1])<=1)){this.paylines.push(line);seen.add(key);}}
  this.config.description='5×3 · 50라인 · 왼쪽부터 연결\n가운데 세 릴의 SCATTER 스택: 무료 7회. 무료 중 중앙 한 칸이 CASH ZONE입니다.\nCASH ZONE에 여왕·투구·방패가 오면 해당 금고의 표시 상금을 지급하고 다음 상금을 베팅 1배씩 올립니다.\n일반 라인 당첨과 CASH ZONE은 각각 한 번 지급합니다. 금고는 매 보너스 2배부터 시작하며 무료 재발동은 없습니다.\n상금·상승 폭·확률·라인 모양은 로컬 규칙입니다. 구매는 같은 독립 무료 보너스로 진입합니다.';
 }
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-gaze';}
 private grid(bet:number,rng:()=>number,conditional=false){if(!this.bets.includes(bet))throw Error('Invalid bet');const high=this.drawingFree?GAZE_MODEL.freeHighByBet[bet]:GAZE_MODEL.baseHighByBet[bet],q=this.drawingFree?GAZE_MODEL.freeGate:GAZE_MODEL.baseGate,b=Array<string>(15);for(let col=0;col<5;col++){const gate=col>0&&col<4&&(conditional||gazeUniform(rng)<q);if(gate){for(let row=0;row<3;row++)b[row*5+col]=this.id('scatter');continue;}const symbol=this.id(gazeOrdinary(high,rng)),stack=gazeUniform(rng)<GAZE_MODEL.stack;for(let row=0;row<3;row++){const id=this.id(gazeOrdinary(high,rng));b[row*5+col]=stack?symbol:id;}}return b;}
 draw(bet:number,rng:()=>number){return this.grid(bet,rng);}
 private gate(b:string[]){return [1,2,3].flatMap(c=>[c,c+5,c+10]).filter(c=>b[c]===this.id('scatter'));}
 private freeGames(base:SpinResult,bet:number,rng:()=>number){const saved=this.drawingFree;this.drawingFree=true;try{const rounds=[base],tiers=[2,2,2];for(let left=6;left>=0;left--){const b=this.draw(bet,rng),fs=[this.frame(b,'reels','중앙 CASH ZONE · 무료 회전',[],{panel:{label:'CASH ZONE',columns:3,values:[...tiers]}}),this.hit(b,bet,'50라인 당첨')],tier=[0,1,2].find(n=>b[7]===this.id(n));
   if(tier!==undefined){const before=[...tiers],paid=this.prize(b,bet,tiers[tier],[7],'중앙 CASH ZONE · '+this.config.symbols[tier].name+' 금고 지급');paid.action='collect';paid.coinAwards=[{cell:7,win:paid.wins[0]}];paid.panel={label:'CASH ZONE',columns:3,values:before,collectIndex:tier};fs.push(this.frame(b,'trigger','중앙 심볼 → 해당 금고 상금',[7],{panel:{label:'CASH ZONE',columns:3,values:before,collectIndex:tier}}),paid);tiers[tier]++;fs.push(this.frame(b,'state','수집 완료 · 다음 금고 상금 +1배',[],{panel:{label:'CASH ZONE',columns:3,values:[...tiers]}}));}
   for(const f of fs)if(!f.panel)f.panel={label:'CASH ZONE',columns:3,values:[...fs[0].panel!.values]};rounds.push(this.round(bet,fs,{freeSpinsRemaining:left}));}
  return this.finish(rounds,{freeSpinsAwarded:7,featureOnly:false});}finally{this.drawingFree=saved;}
 }
 play(b:string[],bet:number,rng:()=>number){this.validate(b,bet);const base=this.ordinary(b,bet),gates=this.gate(b);if(gates.length!==9)return this.finish([base]);base.expansionFeature!.frames.push(this.frame(b,'trigger','중앙 세 SCATTER 스택 · 무료 7회',gates));return this.freeGames(base,bet,rng);}
 prepareBonusPurchase(bet:number,rng:()=>number){const b=this.grid(bet,rng,true),gates=this.gate(b);return this.purchaseFromResult(this.freeGames(this.round(bet,[this.frame(b,'trigger','독립 CASH ZONE 무료 7회',gates)]),bet,rng));}
}
