import type {QuestRow,QuestSnapshot} from './QuestPolicy';

/** Stable groups preserve catalog order and never mutate the server snapshot. */
export function orderedMissions(rows:readonly QuestRow[]):QuestRow[]{
 const rank=(row:QuestRow)=>row.rewardState==='claimed'?2:row.rewardState==='claimable'||row.complete?0:1;
 return rows.map((row,index)=>({row,index})).sort((a,b)=>rank(a.row)-rank(b.row)||a.index-b.index).map(({row})=>row);
}
export function missionAttention(data:QuestSnapshot|null|undefined):boolean{
 return !!data&&data.pendingCoins>0;
}

export function dailyFreeSpinAttention(today:{status:string}|null|undefined):boolean{return !!today&&today.status!=='completed';}
