import {Mask,Node,Sprite,SpriteFrame,UITransform} from 'cc';
import {LOGIN_CHARACTER_ART,loginReelState} from './LoginReelMotion';

/** Three persistent masked reels: update positions/frames, never rebuild per tick. */
export class LoginCharacterReels {
 private readonly frames:SpriteFrame[];
 private readonly reels:Sprite[][]=[];
 private readonly pitch=76;
 constructor(plates:Node[],frames:ReadonlyMap<string,SpriteFrame>){
  this.frames=LOGIN_CHARACTER_ART.map(([id])=>frames.get('login-reel/'+id)).filter((frame):frame is SpriteFrame=>!!frame);
  if(!this.frames.length)this.frames=['raccoon','olympus'].map(id=>frames.get('intro/'+id)).filter((frame):frame is SpriteFrame=>!!frame);
  for(const plate of plates){
   const window=new Node('Login character reel window');window.layer=plate.layer;plate.addChild(window);
   window.setPosition(44,-44);window.addComponent(UITransform).setContentSize(76,76);window.addComponent(Mask).type=Mask.Type.GRAPHICS_RECT;
   const sprites:Sprite[]=[];
   for(let row=0;row<3;row++){
    const node=new Node('Login character strip '+row);node.layer=plate.layer;window.addChild(node);
    node.addComponent(UITransform).setContentSize(64,64);const sprite=node.addComponent(Sprite);sprite.sizeMode=Sprite.SizeMode.CUSTOM;sprites.push(sprite);
   }
   this.reels.push(sprites);
  }
 }
 update(time:number){
  if(!this.frames.length)return;
  for(let reel=0;reel<this.reels.length;reel++){
   const state=loginReelState(time,reel,this.frames.length);
   for(let row=0;row<3;row++){
    const sprite=this.reels[reel][row];if(!sprite.node.isValid)continue;
    sprite.spriteFrame=this.frames[(state.index+row-1+this.frames.length)%this.frames.length];
    sprite.node.setPosition(0,(row-1-state.offset)*this.pitch);
   }
  }
 }
}
