import {SerpentGazeSlot} from './SerpentGazeSlot';
import {EXPANSION_SPECS} from './ExpansionCatalog';
/** Complete native paid-spin witnesses. Offline QA only; no injected boards or banks. */
export const GAZE_AUDIT_SEEDS:Record<string,number>={empty:4146444341,multi:11655961,stack:11655961,free:3246794906,cash0:3246794906,nonPrize:3246794906,cash1:2961003631,mixed:2961003631,cash2:36581847};
export function gazeAudit(params:URLSearchParams){
 const slot=new SerpentGazeSlot(EXPANSION_SPECS.find(s=>s.id==='serpent-gaze-reels')!),outcome=params.get('audit-gaze-case')||params.get('audit-outcome')||'',kind=({'no-win':'empty','multi-win':'multi'} as Record<string,string>)[outcome]||outcome,initial=GAZE_AUDIT_SEEDS[kind];
 if(initial!==undefined){const spin=(bet:number)=>{
  let seed=initial;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;},r=slot.spin(bet,rng);
  if(['free','cash0','cash1','cash2','mixed','nonPrize'].includes(kind)){
   if(r.rounds?.length!==8||r.freeSpinsAwarded!==7)throw Error('Stale gaze free witness');
   const banks=new Set(r.rounds.slice(1).flatMap(q=>q.expansionFeature!.frames).filter(f=>f.coinAwards).map(f=>f.panel!.collectIndex));
   if(kind.startsWith('cash')&&!banks.has(Number(kind.slice(4)))||kind==='mixed'&&banks.size<2||kind==='nonPrize'&&!r.rounds.slice(1).some(q=>!q.expansionFeature!.frames.some(f=>f.coinAwards)))throw Error('Stale gaze CASH witness');
  }
  return r;
 };slot.demoSpin=spin;if(['free','cash0','cash1','cash2','mixed','nonPrize'].includes(kind))slot.bonusDemoSpin=spin;}
 return slot;
}
