export function neonUniform(rng:()=>number){const x=rng();if(!Number.isFinite(x)||x<0||x>=1)throw Error("Invalid Neon uniform");return x;}
export function neonOrdinary(high:number,rng:()=>number){const w=[5*high,6,7,8,10,12,14,16,2];let roll=neonUniform(rng)*w.reduce((a,b)=>a+b,0);for(let n=0;n<w.length;n++){roll-=w[n];if(roll<0)return n===8?"wild":String(n);}return "wild";}
