import {ExpansionSlot,ExpansionFrame,Geometry,expansionCells as cells,randomIndex as ri} from './ExpansionCore';
import {SpinResult} from './SlotMain';
import {TIGER_MODEL,tigerOrdinary,tigerUniform} from './TigerMath';
export class PolarTigerSlot extends ExpansionSlot {
 private drawingTier:number|undefined;
 unit(symbol:number,count:number){return (.025+.015*(8-symbol))*Math.pow(2,Math.max(0,count-3));}
 draw(bet:number,rng:()=>number,g:Geometry=this.geometry){
  if(!this.bets.includes(bet))throw Error('Invalid bet');const high=this.drawingTier===undefined?TIGER_MODEL.baseHighByBet[bet]:TIGER_MODEL.freeHighByTier[this.drawingTier][bet],board=Array.from({length:g.columns*g.rows},()=>this.id(tigerOrdinary(high,rng)));
  if(this.drawingTier===undefined)for(let col=0;col<g.columns;col++)if(tigerUniform(rng)<TIGER_MODEL.scatterPerReel)board[ri(rng,g.rows)*g.columns+col]=this.id('scatter');return board;
 }
 private tierFree(base:SpinResult,bet:number,rng:()=>number,tier:number,each:(board:string[])=>SpinResult,gates:number[]){const saved=this.drawingTier;this.drawingTier=tier;try{return this.freeFromRound(base,bet,rng,8,each,gates);}finally{this.drawingTier=saved;}}
 prepareBonusPurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');const columns=[0,1,2,3,4];for(let i=4;i>0;i--){const j=ri(rng,i+1);[columns[i],columns[j]]=[columns[j],columns[i]];}
  const board=Array.from({length:15},()=>this.id(tigerOrdinary(TIGER_MODEL.baseHighByBet[bet],rng)));columns.slice(0,3).forEach(col=>board[ri(rng,3)*5+col]=this.id('scatter'));
  // Retain the previous purchase's fresh growth0 policy without paid-spin
  // searches or changes to saved growth. Tier0 cannot reach the global cap.
  const saved=this.progress;this.progress={};try{return this.purchaseFromResult(this.play(board,bet,rng));}finally{this.progress=saved;}
 }

 play(board:string[],bet:number,rng:()=>number){
  const state=this.state(bet,[0,0]),previous=state[0],found=cells(board,this.id('scatter'));
  if(state[0]<3){state[1]++;if(state[1]>=10){state[1]=0;state[0]++;}}
  const growth={level:state[0],spins:state[1]},decorate=(frames:ExpansionFrame[])=>frames.map(f=>({...f,growth:{...growth}}));
  const frames:ExpansionFrame[]=decorate([this.frame(board,'reels','성장 단계 '+state[0]),this.hit(board,bet)]);
  if(state[0]>previous)frames.push(this.frame(board,'trigger','10회 플레이 · 새 무료 피처 해금',[],{growth}));
  const base=this.round(bet,frames);
  if(found.length<3)return this.progressResult(this.finish([base]),bet,state);
  const result=this.tierFree(base,bet,rng,state[0],b=>{
   const after=[...b],v=b.map(()=>0),wilds=cells(b,this.id('wild')),fs:ExpansionFrame[]=[this.frame(b,'reels','성장 단계 '+state[0]+' 무료 회전')],moves:{from:number;to:number;symbol:string}[]=[];
   if(state[0]>=1)wilds.forEach(c=>v[c]=2);
   if(state[0]>=2)for(const c of wilds)for(let row=0;row<3;row++){const target=row*5+c%5;if(after[target]!==this.id('wild'))moves.push({from:c,to:target,symbol:this.id('wild')});after[target]=this.id('wild');v[target]=2;}
   if(state[0]>=3&&wilds.length){const col=ri(rng,5);for(let row=0;row<3;row++){const target=row*5+col;if(after[target]!==this.id('wild'))moves.push({from:wilds[0],to:target,symbol:this.id('wild')});after[target]=this.id('wild');v[target]=3;}}
   if(wilds.length&&state[0]>=1){fs.push(this.frame(b,'trigger','해금 능력 발동',wilds));if(moves.length)fs.push(this.frame(after,'move','호랑이 발자국 · WILD 확장',moves.map(m=>m.to),{moves,moveMode:'copy',values:v}));fs.push(this.frame(after,'effect','배수 → 확장 → 추가 WILD',cells(after,this.id('wild')),{values:v}));}
   fs.push(this.hit(after,bet,'성장 피처 당첨',this.geometry,{values:v,wildMode:'sum'}));return this.round(bet,decorate(fs));
  },found);
  return this.progressResult(result,bet,state);
 }
}
