import{JUNGLE_HEIGHT_MODEL}from'./JungleHeightMath';
export type JungleHeightInputs={sign:number;wild:number;coin:number;baseZeroByBet:Record<number,number>;freeZeroByBet:Record<number,number>};
const D:JungleHeightInputs=JUNGLE_HEIGHT_MODEL;
function checked(rng:()=>number){return()=>{const v=rng();if(!Number.isFinite(v)||v<0||v>=1)throw Error('Invalid Jungle uniform');return v;};}
function regular(id:string,bet:number,col:number,u:number,free:boolean){const z=(free?D.freeZeroByBet:D.baseZeroByBet)[bet],w=col>0&&col<4?D.wild:0;if(!Number.isFinite(z))throw Error('Invalid Jungle bet');const p=[z,...[6,7,8,10,12,14,16].map(v=>(1-z-w)*v/73),w];let n=8;for(let i=0;i<p.length;i++){u-=p[i];if(u<0){n=i;break;}}return id+'-'+(n===8?'wild':n);}
/** Fixed three independent categorical inputs per cell; source gate occurs at most once per reel. */
export function jungleInputBoard(id:string,bet:number,rng:()=>number,rows:number,free=false,opening:string[]=[]){if(!Number.isFinite(D.baseZeroByBet[bet])||!Number.isInteger(rows)||rows<3||rows>6||opening.length%5||opening.length>rows*5)throw Error('Invalid Jungle board input');rng=checked(rng);const b=[...opening];for(let c=b.length;c<rows*5;c++){const sign=rng(),coin=rng(),u=rng(),col=c%5,has=b.some((v,i)=>i%5===col&&v===id+'-scatter');b.push(!free&&!has&&sign<D.sign?id+'-scatter':coin<D.coin?id+'-prize':regular(id,bet,col,u,free));}return b;}
function choose(weights:number[],rng:()=>number){let u=rng()*weights.reduce((a,b)=>a+b,0);for(let i=0;i<weights.length;i++){u-=weights[i];if(u<0)return i;}return weights.length-1;}
/** Direct conditional >=3 visible reel gates, including the original random3..6 height law. */
export function jungleInputPurchase(id:string,bet:number,rng:()=>number){if(!Number.isFinite(D.baseZeroByBet[bet]))throw Error('Invalid Jungle bet');rng=checked(rng);const q=[3,4,5,6].map(h=>1-(1-D.sign)**h),mean=q.reduce((a,b)=>a+b,0)/4,mask=choose(Array.from({length:32},(_,mask)=>{const n=Array.from({length:5},(_,c)=>(mask>>c)&1).reduce((a,b)=>a+b,0);return n>=3?mean**n*(1-mean)**(5-n):0;}),rng),heights=Array.from({length:5},(_,col)=>3+choose(q.map(v=>(mask>>col)&1?v:1-v),rng)),positions=heights.map((h,col)=>(mask>>col)&1?choose(Array.from({length:h},(_,r)=>D.sign*(1-D.sign)**r),rng):-1),board:string[]=[];
 for(let c=0;c<Math.max(...heights)*5;c++){const col=c%5,row=Math.floor(c/5),sign=rng(),coin=rng(),u=rng(),seen=board.some((v,i)=>i%5===col&&v===id+'-scatter'),gate=row<heights[col]?positions[col]===row:!seen&&sign<D.sign;board.push(gate?id+'-scatter':coin<D.coin?id+'-prize':regular(id,bet,col,u,false));}
 return{board,heights};
}
