import {Color,Font,Graphics,Label,Node,Sprite,SpriteFrame,UITransform} from 'cc';
import {i18n} from '../services/Localization';
import {pocketSettlementFrame} from './PocketSettlementLayout';

/** The shared In My Pocket payout bank, temporarily over the reel/WIN seam. */
export class PocketSettlementPanel {
 readonly node:Node;
 readonly amount:Label;
 constructor(parent:Node,win:Node,font:Font|null,initial='0',art?:SpriteFrame){
  const bounds=win.getComponent(UITransform)!;
  const frame=pocketSettlementFrame({x:win.position.x,y:-win.position.y,width:bounds.width});
  const panel=this.node=new Node('Pocket settlement panel');panel.layer=parent.layer;parent.addChild(panel);panel.setPosition(frame.x,-frame.y);
  const transform=panel.addComponent(UITransform);transform.setAnchorPoint(0,1);transform.setContentSize(frame.width,frame.height);
  if(art){const sprite=panel.addComponent(Sprite);sprite.sizeMode=Sprite.SizeMode.CUSTOM;sprite.spriteFrame=art;transform.setContentSize(frame.width,frame.height);}
  else{const g=panel.addComponent(Graphics);for(const [inset,color]of [[0,'#8b592b'],[3,'#df9d35'],[7,'#164d58']] as const){g.fillColor=new Color(color);g.roundRect(inset,-frame.height+inset,frame.width-inset*2,frame.height-inset*2,Math.max(4,16-inset));g.fill();}}
  const label=(name:string,text:string,y:number,size:number,height:number,color:string)=>{
   const node=new Node(name);node.layer=panel.layer;panel.addChild(node);node.setPosition(frame.width*.09,-y);
   const t=node.addComponent(UITransform);t.setAnchorPoint(0,1);t.setContentSize(frame.width*.82,height);
   const l=node.addComponent(Label);l.string=text;l.font=font;l.fontFamily=i18n.fontFamily;l.fontSize=size;l.lineHeight=size*1.15;l.color=new Color(color);l.isBold=!font;l.enableWrapText=false;l.overflow=Label.Overflow.SHRINK;l.horizontalAlign=Label.HorizontalAlign.CENTER;l.verticalAlign=Label.VerticalAlign.CENTER;
   l.enableOutline=true;l.outlineColor=new Color('#174858');l.outlineWidth=2;
   // Label attachment resets UITransform bounds; apply the final inset afterward.
   t.setContentSize(frame.width*.82,height);return l;
  };
  this.amount=label('Pocket settlement amount',initial,19,34,54,'#fff0af');
 }
 destroy(){if(this.node.isValid){this.node.removeFromParent();this.node.destroy();}}
}
