import {FlowControl} from './FlowControl';

/** Touch acceleration belongs only to the currently active opening/spin. */
export class SpinMotion extends FlowControl {
 private depth=0;
 get active(){return this.depth>0;}
 quick(){if(!this.active)return false;this.setSpeed(3);return true;}
 async run<T>(action:()=>Promise<T>):Promise<T>{
  if(this.depth++===0)this.setSpeed(1);
  try{return await action();}
  finally{if(--this.depth===0)this.setSpeed(1);}
 }
}
