/** Fixed local independent reel windows, drawn before any source award.
 * This is not a private provider reel reconstruction. Each reel chooses its
 * focus symbol and uniform row independently; remaining cells are nonpay seals.
 * The first reel has an independent inactive window, the fifth two focus cells.
 * No winning board search, payout gate, rescue or state-dependent input. */
export const SEAL_MODEL={"focus":[0.038571428571428576,0.038571428571428576,0.038571428571428576,0.038571428571428576,0.038571428571428576,0.038571428571428576,0.038571428571428576,0.7,0.03],"firstActive":0.8444071801625146,"lastDoubleProbability":1,"prizeProbabilities":[0.13873482985355645,0.13873482985355645,0.7225303402928871]};
export function sealUniform(rng:()=>number){const value=rng();if(!Number.isFinite(value)||value<0||value>=1)throw Error('Invalid seal uniform');return value;}
function category(weights:number[],rng:()=>number){const value=sealUniform(rng);let sum=0;for(let i=0;i<weights.length;i++){sum+=weights[i];if(value<sum)return i;}return weights.length-1;}
export function drawSealWindow(rng:()=>number){const active=sealUniform(rng)<SEAL_MODEL.firstActive,board=Array(15).fill(9) as number[];for(let col=0;col<5;col++){const symbol=category(SEAL_MODEL.focus,rng),row=Math.floor(sealUniform(rng)*3);if(col===0&&!active)continue;for(let r=0;r<3;r++)if(col===4?r!==row:r===row)board[r*5+col]=symbol;}return board;}
export function sealPrizeMultiplier(rng:()=>number){return [1,2,5][category(SEAL_MODEL.prizeProbabilities,rng)];}
