import {ExpansionSlot,ExpansionFrame,ExpansionAction,Geometry,expansionCells as cells,randomIndex as ri} from './ExpansionCore';
import {SpinResult} from './SlotMain';
import {JOEY_MODEL,joeyUniform,joeyOrdinary} from './JoeyMath';
export class JoeyPuzzleSlot extends ExpansionSlot {
 private drawingFree=false;
 unit(symbol:number,count:number){return (.025+.015*(8-symbol))*Math.pow(2,Math.max(0,count-3));}
 draw(bet:number,rng:()=>number,g:Geometry=this.geometry){
  if(!this.bets.includes(bet)||g.columns!==5||g.rows!==3)throw Error('Invalid Joey wager or geometry');const high=this.drawingFree?JOEY_MODEL.freeHighByBet[bet]:JOEY_MODEL.baseHighByBet[bet],piece=this.drawingFree?JOEY_MODEL.freePiece:JOEY_MODEL.basePiece,board=Array.from({length:15},()=>this.id(joeyOrdinary(high,rng)));
  for(let col=0;col<5;col++)if(joeyUniform(rng)<piece)board[Math.floor(joeyUniform(rng)*3)*5+col]=this.id('scatter');return board;
 }
 frame(board:string[],action:ExpansionAction,caption:string,cells:number[]=[],extra:Partial<ExpansionFrame>={},g:Geometry=this.geometry):ExpansionFrame{
  if(!extra.wins?.length)return super.frame(board,action,caption,cells,extra,g);
  // Keep the source key order and original win references. Its serialized
  // wins clone is overwritten, so omit only that redundant array traversal.
  const copied=JSON.parse(JSON.stringify(extra,function(key,value){return this===extra&&key==='wins'?[]:value;}));
  return{action,caption,board:[...board],columns:g.columns,rows:g.rows,cells:[...cells],...copied,wins:extra.wins};
 }
 get bonusTriggerCount(){return Number.POSITIVE_INFINITY;}
 spin(bet:number,rng:()=>number=Math.random){this.columns=this.spec.columns;this.rows=this.spec.rows;return super.spin(bet,rng);}
 play(board:string[],bet:number,rng:()=>number){
  const g={columns:5,rows:3},state=this.state(bet,[0,0]),puzzle=state[1]||0,found=cells(board,this.id('scatter'));
  const marked=(mask:number)=>Array.from({length:9},(_,i)=>mask>>i&1),count=(mask:number)=>marked(mask).reduce((a,b)=>a+b,0);
  const panel=(mask:number)=>({label:'퍼즐 '+(puzzle+1)+' · 3×3',values:marked(mask),columns:3});
  const step=(mask:number,phase:NonNullable<ExpansionFrame['joeyPuzzle']>['phase'],extra:Partial<NonNullable<ExpansionFrame['joeyPuzzle']>>={})=>({puzzle:puzzle+1,mask,phase,...extra});
  const hit=this.hit(board,bet,'일반 라인 당첨',g);hit.panel=panel(state[0]);hit.joeyPuzzle=step(state[0],'collect');
  const frames:ExpansionFrame[]=[this.frame(board,'reels','퍼즐 조각 착지',[],{panel:panel(state[0]),joeyPuzzle:step(state[0],'collect')},g),hit];
  for(const cell of found){
   const piece=ri(rng,9),before=state[0],fresh=!(before>>piece&1);state[0]|=1<<piece;
   frames.push(this.frame(board,'trigger','조각 '+(piece+1)+' 공개',[cell],{panel:panel(before),joeyPuzzle:step(before,'reveal',{piece,fresh})},g));
   frames.push(this.frame(board,'collect',fresh?'새 조각 → 퍼즐 칸 '+(piece+1):'이미 모은 조각 · 진행 유지',[cell],{panel:{...panel(before),active:[piece]},joeyPuzzle:step(before,'piece',{piece,fresh}),meter:{label:'퍼즐 '+(puzzle+1),before:count(before),after:count(state[0]),target:9,items:[{cell,value:fresh?1:0}]}},g));
   frames.push(this.frame(board,'state','퍼즐 '+count(state[0])+'/9 확인',[],{panel:{...panel(state[0]),active:[piece]},joeyPuzzle:step(state[0],'confirmed',{piece,fresh})},g));
  }
  const base=this.round(bet,frames);
  if(state[0]!==511)return this.progressResult(this.finish([base]),bet,[state[0],puzzle]);
  frames.push(this.frame(board,'trigger','9조각 완성 · 3개 독립 릴판 무료 6회',found,{panel:panel(511),joeyPuzzle:step(511,'complete')},g));
  return this.progressResult(this.freePuzzle(base,bet,rng,puzzle),bet,[0,(puzzle+1)%3]);
 }
 private freePuzzle(base:SpinResult,bet:number,rng:()=>number,puzzle:number){
  const saved=this.drawingFree;this.drawingFree=true;try{const g={columns:5,rows:3},step=(mask:number,phase:NonNullable<ExpansionFrame['joeyPuzzle']>['phase'],extra:Partial<NonNullable<ExpansionFrame['joeyPuzzle']>>={})=>({puzzle:puzzle+1,mask,phase,...extra});
  const rounds=[base],groups={count:3,rows:3,columns:5},freeGeometry={columns:5,rows:9};
  for(let left=5;left>=0;left--){
   const boards=Array.from({length:3},()=>this.draw(bet,rng,g)),all=boards.flat(),fs:ExpansionFrame[]=[this.frame(all,'reels','3개 독립 릴판 동시 회전',[],{boardGroups:groups,joeyPuzzle:step(511,'spin',{spin:6-left})},freeGeometry)];
   for(const [index,b]of boards.entries()){
    const wins=this.evaluate(b,bet,g).wins.map(win=>({...win,line:win.line+index*this.paylines.length,cells:win.cells.map(cell=>cell+index*15)}));
    fs.push(this.frame(all,'win',(index+1)+'번 릴판 · 별도 라인 당첨',wins.flatMap(w=>w.cells),{wins,boardGroups:groups,joeyPuzzle:step(511,'pay',{spin:6-left,board:index})},freeGeometry));
   }
   rounds.push(this.round(bet,fs,{freeSpinsRemaining:left}));
  }
  return this.finish(rounds,{freeSpinsAwarded:6,featureOnly:false});
  }finally{this.drawingFree=saved;}
 }
 prepareBonusPurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  // Purchase directly enters the completed independent puzzle. It does not
  // play paid spins or inject/consume the player's saved collection progress.
  const board=Array.from({length:15},()=>this.id(joeyOrdinary(JOEY_MODEL.baseHighByBet[bet],rng))),base=this.round(bet,[this.frame(board,'trigger','9조각 완성 · 3개 독립 릴판 무료 6회',[],{panel:{label:'퍼즐 1 · 3×3',values:Array(9).fill(1),columns:3},joeyPuzzle:{puzzle:1,mask:511,phase:'complete'}})]);
  return this.purchaseFromResult(this.freePuzzle(base,bet,rng,0));
 }

}
