export function stargemUniform(rng:()=>number){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid Stargem uniform');return u;}
export function stargemOrdinary(high:number,wild:number,rng:()=>number){const w=[5*high,6,7,8,10,12,14,16,wild];let x=stargemUniform(rng)*w.reduce((a,b)=>a+b,0);for(let k=0;k<w.length;k++){x-=w[k];if(x<0)return k===8?'wild':String(k);}return 'wild';}
