import {Node,UITransform,Graphics,Color,Vec3,Tween,tween,EventTouch,input,Input} from 'cc';
import {gameAudio} from '../services/GameAudio';

const buttonPressCancellation=new WeakMap<Node,()=>void>();
/** A navigation gesture releases the pressed face without activating its button. */
export function cancelButtonPress(node:Node){buttonPressCancellation.get(node)?.();}

/** Beveled face kept inside the existing touch rectangle. */
export function buttonFace(node:Node,fill:string,border:string,selected=false,disabled=false){
 const t=node.getComponent(UITransform)!,w=t.width,h=t.height,x=-t.anchorX*w,y=-t.anchorY*h;
 const g=node.getComponent(Graphics)||node.addComponent(Graphics),r=Math.min(12,h*.2);g.clear();
 g.fillColor=new Color('#101625');g.roundRect(x,y,w,h,r);g.fill();
 g.fillColor=new Color(fill);g.roundRect(x+1,y+5,w-2,h-6,r);g.fill();
 g.strokeColor=new Color(border);g.lineWidth=selected?3:2;g.roundRect(x+2,y+6,w-4,h-9,r-1);g.stroke();
 g.fillColor=new Color(255,255,255,disabled?12:42);g.roundRect(x+8,y+h-9,w-16,3,1);g.fill();
 if(selected){g.fillColor=new Color('#fff0ba');g.roundRect(x+w*.32,y+8,w*.36,3,1);g.fill();}
}

export interface ButtonFeedbackOptions {
 /** Scrollable cards must not activate after their owning ScrollView cancels. */
 cancelOnNodeCancel?:boolean;
 /** Dynamic lists must not run a callback captured by a node replaced on render. */
 requireLiveNode?:boolean;
}

/** Immediate press feedback; a visibly pressed button commits when that pointer is released. */
export function bindButtonFeedback(node:Node,activate:()=>void,options:ButtonFeedbackOptions={}){
 let pointer:number|null=null,pressed=false,origin:Vec3|null=null,base:Vec3|null=null,shade:Node|null=null,startEvent:EventTouch|null=null;
 const release=()=>{
  if(!origin||!base||!node.isValid)return;
  Tween.stopAllByTarget(node);
  tween(node).to(.16,{position:origin,scale:base},{easing:'backOut'}).start();
  if(shade?.isValid)shade.active=false;
 };
 function stopReleaseWatch(){
  input.off(Input.EventType.TOUCH_START,supersede);
  input.off(Input.EventType.TOUCH_END,finish);
  input.off(Input.EventType.TOUCH_CANCEL,cancel);
 }
 function abort(){
  pointer=null;pressed=false;startEvent=null;stopReleaseWatch();release();
 }
 buttonPressCancellation.set(node,abort);
 function supersede(e:EventTouch){
  // Pointer IDs are reused. If a release was lost while the UI rebuilt or the
  // app lost focus, a later gesture must never commit the old button action.
  if(pointer!==null&&e!==startEvent)abort();
 }
 function finish(e:EventTouch){
  if(pointer!==e.getID())return;
  e.propagationStopped=true;
  // A live-data render can replace the visible node between press and release.
  // Once the user saw the pressed state, the captured action still belongs to that gesture.
  const commit=pressed&&(!options.requireLiveNode||node.isValid&&(node as Node&{activeInHierarchy?:boolean}).activeInHierarchy!==false);
  pointer=null;pressed=false;startEvent=null;stopReleaseWatch();release();
  if(commit)activate();
 }
 function cancel(e:EventTouch){
  if(pointer!==e.getID())return;
  abort();
 }
 node.on(Node.EventType.TOUCH_START,(e:EventTouch)=>{
  if(pointer!==null)return;e.propagationStopped=true;pointer=e.getID();startEvent=e;
  // Capture after layout/reparenting, not while the button is being constructed.
  if(!origin){origin=node.position.clone();base=node.scale.clone();}
  Tween.stopAllByTarget(node);const t=node.getComponent(UITransform)!;
  node.setScale(base!.x*.9,base!.y*.9,base!.z);
  node.setPosition(origin.x+(0.5-t.anchorX)*t.width*base!.x*.1,origin.y+(0.5-t.anchorY)*t.height*base!.y*.1-3,origin.z);
  // Shrinking the button can make Cocos report TOUCH_CANCEL for an edge press.
  // Watch the global release because the scaled node may stop owning the pointer.
  pressed=true;
  input.on(Input.EventType.TOUCH_START,supersede);
  input.on(Input.EventType.TOUCH_END,finish);
  input.on(Input.EventType.TOUCH_CANCEL,cancel);
  if(!shade?.isValid){shade=new Node('Button pressed tint');shade.layer=node.layer;node.addChild(shade);const g=shade.addComponent(Graphics);g.fillColor=new Color(8,15,30,65);g.roundRect(-t.anchorX*t.width,-t.anchorY*t.height,t.width,t.height,Math.min(12,t.height*.2));g.fill();}
  shade.active=true;shade.setSiblingIndex(node.children.length-1);gameAudio.cue('tap');
 });
 // ScrollView can cancel its child before the finger is actually released.
 // Keep the press latched; the global END/CANCEL listener above owns completion.
 node.on(Node.EventType.TOUCH_CANCEL,(e:EventTouch)=>{if(pointer!==e.getID())return;if(options.cancelOnNodeCancel)cancel(e);else e.propagationStopped=true;});
 node.on(Node.EventType.TOUCH_END,finish);
}
