export const RAIL_WEIGHTS=[5,6,7,8,10,12,14,16,2];
const pools=new Map<RailInputProfile,Map<number,{high:number;weights:number[];sum:number}>>();
export function railUniform(rng:()=>number){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid Rail random value');return u;}
export function railCellInput(bet:number,rng:()=>number,profile:RailInputProfile){
 const u=railUniform(rng);if(u>=1-profile.coin)return 'coin';const high=profile.highByBet[bet]??1;
 let byBet=pools.get(profile);if(!byBet){byBet=new Map();pools.set(profile,byBet);}let pool=byBet.get(bet);
 if(!pool||pool.high!==high){const weights=RAIL_WEIGHTS.map((w,i)=>w*(i===0?high:1));pool={high,weights,sum:weights.reduce((n,w)=>n+w,0)};byBet.set(bet,pool);}
 let sample=u/(1-profile.coin)*pool.sum;for(let i=0;i<9;i++){sample-=pool.weights[i];if(sample<0)return i===8?'wild':i;}return 7;
}
